window.TADABBUR_ANAM = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الأنعام (٦)، سورةٌ مكّيّةٌ في التوحيد وإبطالِ الشرك. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":6,"name":"الأنعام","total_ayahs":165,"audio":[1,59,95,102,103,151,152,153,162,163],"passages":[{"title":"الحمدُ للخالق، وإعراضُ المكذّبين","range":[1,10],"theme":"توحيدُ الخالقِ المدبِّر، وعنادُ من يعدل به غيرَه ويعرض عن آياته","verses":[{"n":1,"reflection":{"text":"«الحمد لله الذي خلق السماوات والأرض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون»: افتُتحت السورةُ بحمد الله على خلقه السماواتِ والأرضَ وجعلِه الظلماتِ والنور؛ فمن انفرد بالخلق استحقّ الحمدَ والعبادة؛ ومع هذا فالكافرون يجعلون له عِدلًا وشريكًا يعبدونه، وهذا غايةُ الظلم والعناد. فمن خلق كلَّ شيءٍ لا يُسوَّى به شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الخالقِ بالحمد والعبادة."},"action":{"text":"احمد الله على خلقه ونعمه، ولا تجعل له عِدلًا في عبادتك أو محبّتك."}},{"n":2,"reflection":{"text":"«هو الذي خلقكم من طين ثم قضى أجلا وأجل مسمى عنده ثم أنتم تمترون»: هو الذي خلق أباكم آدمَ من طين، وقدّر لكلٍّ أجلًا للموت، وأجلًا آخرَ مسمّى عنده للبعث؛ ثمّ أنتم، مع وضوح قدرته، تشكّون في البعث. فمن خلقكم أوّلًا قادرٌ على إعادتكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ لمن قدر على الخلق."},"action":{"text":"اعمل لأجلك المسمّى، ولا تشكّ في البعث، فمن خلقك من طينٍ يعيدك."}},{"n":3,"reflection":{"text":"«وهو الله في السماوات وفي الأرض يعلم سركم وجهركم ويعلم ما تكسبون»: هو المعبودُ بحقٍّ في السماوات والأرض، المستحقُّ للعبادة فيهما؛ يعلم ما تُسرّون وما تُعلنون، ويعلم أعمالكم فيجازيكم؛ فعلمُه محيطٌ بكم. فراقبه في سرّك كما في علنك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله العالمِ بالسرّ والجهر."},"action":{"text":"استحضر علمَ الله بسرّك وعلنك، فأصلِح باطنك كما تُصلح ظاهرك."}},{"n":4,"reflection":{"text":"«وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين»: لا تأتي المكذّبين آيةٌ من آيات الله (كونيّةٌ أو قرآنيّة) إلا أعرضوا عنها ولم يتدبّروها؛ فالإعراضُ دأبُهم، لا نقصَ في الآيات. فالحجّةُ قائمةٌ، والعلّةُ في قلوبهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الإعراضِ عن آيات الله والإقبالِ عليها."},"action":{"text":"لا تمرّ على آيات الله معرضًا، بل تدبّرها لتنتفع بها."}},{"n":5,"reflection":{"text":"«فقد كذبوا بالحق لما جاءهم فسوف يأتيهم أنباء ما كانوا به يستهزئون»: كذّبوا بالقرآن الحقّ حين جاءهم؛ فسوف تأتيهم عواقبُ استهزائهم وأخبارُ ما سخروا منه حين ينزل بهم العذاب؛ فالاستهزاءُ بالحقّ عاقبتُه وخيمة. فمن سخر بالحقّ لحقه سخريتُه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بالحقّ وعاقبتِه."},"action":{"text":"عظّم الحقَّ ولا تستهزئ به، فعاقبةُ الساخرِ أن يحيق به ما سخر منه."}},{"n":6,"reflection":{"text":"«ألم يروا كم أهلكنا من قبلهم من قرن مكناهم في الأرض ما لم نمكن لكم وأرسلنا السماء عليهم مدرارا وجعلنا الأنهار تجري من تحتهم فأهلكناهم بذنوبهم وأنشأنا من بعدهم قرنا آخرين»: ألم يعتبروا بمن أهلكنا قبلهم من أممٍ كانوا أقوى منهم تمكينًا وأوسعَ رزقًا (مطرًا وأنهارًا)، فأهلكهم الله بذنوبهم وأنشأ غيرهم؟ فالقوّةُ والنعمةُ لا تمنع عقوبةَ المصرّ. فاعتبروا بمصارع الأمم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعواقبِ الأمم المكذّبة."},"action":{"text":"تأمّل مصارعَ الأمم الظالمة، واعلم أنّ الذنوبَ تُهلك مهما كثُرت النعم."}},{"n":7,"reflection":{"text":"«ولو نزلنا عليك كتابا في قرطاس فلمسوه بأيديهم لقال الذين كفروا إن هذا إلا سحر مبين»: لو أنزلنا عليك كتابًا مكتوبًا في ورقٍ يرونه ويلمسونه لقال المعاندون: ما هذا إلا سحرٌ ظاهر؛ فعنادُهم لا تنفع معه الآيات؛ لأنّ المشكلةَ في إرادتهم لا في البيّنة. فالمعاندُ لا يُقنعه دليل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ العنادَ لا يُشفى بكثرة الأدلّة."},"action":{"text":"لا تُتعِب نفسك مع معاندٍ لا يريد الحقّ، فبيّنتُه لا تنقصه بل إرادتُه."}},{"n":8,"reflection":{"text":"«وقالوا لولا أنزل عليه ملك ولو أنزلنا ملكا لقضي الأمر ثم لا ينظرون»: اقترحوا أن يُنزَّل معه ملكٌ يُرى؛ ولو أنزلنا ملكًا على صورته الحقيقيّة ثمّ لم يؤمنوا لعُجّل لهم العذابُ ولم يُمهَلوا؛ فاقتراحُهم لو أُجيب لكان هلاكهم. فرحمةُ الله في إمهالهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله وتركُ اقتراحِ الآيات."},"action":{"text":"لا تقترح على الله آياتٍ، فتدبيرُه رحمةٌ، وإجابةُ اقتراحك قد تكون هلاكك."}},{"n":9,"reflection":{"text":"«ولو جعلناه ملكا لجعلناه رجلا وللبسنا عليهم ما يلبسون»: لو جعلنا الرسولَ ملكًا لجعلناه في صورة رجلٍ ليطيقوا رؤيته والأخذَ عنه، فيعود عليهم اللبسُ الذي فرّوا منه؛ فإرسالُ الرسول بشرًا من جنسهم رحمةٌ وحكمة. فبعثةُ البشرِ رحمةٌ لا نقص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ حكمةِ بعثةِ الرسول من جنس البشر."},"action":{"text":"اشكر أن جعل رسولك بشرًا تفهم عنه وتتأسّى به، فذاك رحمةٌ وحكمة."}},{"n":10,"reflection":{"text":"«ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون»: تسليةٌ للنبي ﷺ: قد استُهزئ برسلٍ قبلك، فأحاط بالساخرين العذابُ الذي استعجلوه واستهزؤوا به؛ فسنّةُ الله في الساخرين واحدة؛ فاصبر كما صبروا. فعاقبةُ الاستهزاءِ بالرسل الهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الاستهزاء اقتداءً بالرسل."},"action":{"text":"اصبر على من يستهزئ بدينك، فعاقبةُ الساخرين حاقت بهم كما حاقت بمن قبلهم."}}]},{"title":"لله ما في الكون، وكتب على نفسه الرحمة","range":[11,18],"theme":"الاعتبارُ بعواقب المكذّبين، وأنّ الملكَ لله كتب الرحمةَ على نفسه، وهو القاهرُ النافعُ الضارّ","verses":[{"n":11,"reflection":{"text":"«قل سيروا في الأرض ثم انظروا كيف كان عاقبة المكذبين»: قل لهم: سيروا في الأرض متأمّلين آثارَ الأمم المكذّبة كيف كان مصيرُهم، لتعتبروا؛ فالسيرُ للعبرة لا للهو. فالتاريخُ موعظةٌ لمن تأمّل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ المكذّبين عند التأمّل."},"action":{"text":"تأمّل عواقبَ المكذّبين في التاريخ والآثار لتزداد يقينًا بسنّة الله."}},{"n":12,"reflection":{"text":"«قل لمن ما في السماوات والأرض قل لله كتب على نفسه الرحمة ليجمعنكم إلى يوم القيامة لا ريب فيه الذين خسروا أنفسهم فهم لا يؤمنون»: قل: لمن ملكُ الكون؟ ثمّ أجِب: لله؛ وقد كتب على نفسه الرحمةَ تفضّلًا (وفي الحديث: إنّ رحمتي سبقت غضبي)؛ وليجمعنّكم ليوم القيامة الذي لا شكّ فيه؛ والخاسرون هم الذين لا يؤمنون. فرحمتُه سبقت، والبعثُ حقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحمن"],"heart_state":{"text":"الرجاءُ في رحمةِ الله التي كتبها على نفسه."},"action":{"text":"ارجُ رحمةَ الله التي سبقت غضبه، واعمل ليوم الجمع الذي لا ريب فيه."}},{"n":13,"reflection":{"text":"«وله ما سكن في الليل والنهار وهو السميع العليم»: لله كلُّ ما استقرّ في الليل والنهار من المخلوقات، فالكلُّ ملكُه وتحت تدبيره؛ وهو السميعُ لأصواتهم، العليمُ بأحوالهم؛ فلا يخفى عليه شيء. فمن هذا ملكُه وعلمُه هو المعبودُ وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"استحضارُ سمعِ الله وعلمِه بكلّ ساكنٍ ومتحرّك."},"action":{"text":"اعلم أنّ كلَّ ما في الكون ملكُ الله، يسمع ويعلم، فاعبده وحده."}},{"n":14,"reflection":{"text":"«قل أغير الله أتخذ وليا فاطر السماوات والأرض وهو يطعم ولا يطعم قل إني أمرت أن أكون أول من أسلم ولا تكونن من المشركين»: قل منكرًا: أأتّخذ غيرَ الله وليًّا وهو مبدع السماوات والأرض، يرزق ولا يُرزق، غنيٌّ عن خلقه؟ وأُمرتُ أن أكون أوّلَ المسلمين من هذه الأمّة، ونُهيتُ عن الشرك. فالوليُّ الحقُّ هو الخالقُ الرازق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ الله وحده وليًّا لأنّه الخالقُ الرازق."},"action":{"text":"اتّخذ الله وحده وليًّا، فهو الغنيُّ الذي يرزق ولا يُرزق، ولا تشرك به."}},{"n":15,"reflection":{"text":"«قل إني أخاف إن عصيت ربي عذاب يوم عظيم»: قل: إنّي مع مكانتي أخاف إن عصيتُ ربّي عذابَ يومٍ عظيم؛ فإذا كان النبيُّ يخاف فغيرُه أولى؛ والخوفُ من عذاب الله يحمل على الطاعة. فالتقوى خوفٌ يثمر عملًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"خوفُ عذابِ الله الباعثُ على الطاعة."},"action":{"text":"اجعل خوفَ عذاب الله حاجزًا لك عن معصيته، فحتى النبيُّ كان يخافه."}},{"n":16,"reflection":{"text":"«من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين»: من يُصرَف عنه عذابُ ذلك اليوم العظيم فقد رحمه الله؛ وذلك هو الفوز الظاهر البيّن؛ فالنجاةُ من النار غايةُ الفوز. فأعظمُ الرحمةِ النجاةُ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ النجاةِ من عذاب ذلك اليوم رحمةً وفوزًا."},"action":{"text":"اعمل لتُصرف عنك النارُ يومَ القيامة، فتلك رحمةٌ وفوزٌ مبين."}},{"n":17,"reflection":{"text":"«وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يمسسك بخير فهو على كل شيء قدير»: إن أصابك الله بضرٍّ فلا يقدر على رفعه أحدٌ سواه، وإن أصابك بخيرٍ فلا رادّ لفضله، وهو على كلّ شيء قدير؛ فالنفعُ والضرُّ بيده وحده؛ فلا تعلّق قلبك بسواه. فمن بيده كلُّ شيءٍ يُرجى ويُخاف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["القدير"],"heart_state":{"text":"تعليقُ القلبِ بالله وحده في الضرّ والنفع."},"action":{"text":"علّق رجاءك وخوفك بالله وحده، فلا كاشفَ لضرّك ولا مانعَ لخيره سواه."}},{"n":18,"reflection":{"text":"«وهو القاهر فوق عباده وهو الحكيم الخبير»: هو الغالبُ القاهرُ فوق عباده، خضع له كلُّ شيء وذلّ لعظمته؛ وهو الحكيمُ في تدبيره، الخبيرُ بأحوال خلقه؛ فقهرُه مقرونٌ بحكمةٍ وعلم. فاخضع لمن قهر كلَّ شيءٍ بحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["القاهر","الحكيم","الخبير"],"heart_state":{"text":"الخضوعُ لله القاهرِ الحكيمِ الخبير."},"action":{"text":"اخضع لله القاهرِ فوق عباده، واطمئن أنّ قهره مقرونٌ بحكمةٍ وخبرة."}}]},{"title":"شهادةُ الله بالتوحيد، وأظلمُ الناس","range":[19,25],"theme":"الله أكبرُ شهادةً على التوحيد، وأظلمُ الناسِ مفترٍ أو مكذّب، وحالُ من طُبع على قلبه","verses":[{"n":19,"reflection":{"text":"«قل أي شيء أكبر شهادة قل الله شهيد بيني وبينكم وأوحي إلي هذا القرآن لأنذركم به ومن بلغ أئنكم لتشهدون أن مع الله آلهة أخرى قل لا أشهد قل إنما هو إله واحد وإنني بريء مما تشركون»: قل: أعظمُ شهادةٍ شهادةُ الله، وهو شهيدٌ بيني وبينكم على صدقي؛ وأُوحي إليّ هذا القرآن لأنذركم به وأُنذر كلَّ من بلغه إلى قيام الساعة؛ ثمّ تبرّأ من شركهم: إنّما هو إلهٌ واحدٌ وأنا بريءٌ ممّا تشركون. فالقرآنُ نذيرٌ لكلّ من بلغه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتزازُ بالتوحيد والبراءةُ من الشرك."},"action":{"text":"أعلن توحيدك وابرأ من كلّ شرك، واعلم أنّ القرآن نذيرٌ لك ما بلغك."}},{"n":20,"reflection":{"text":"«الذين آتيناهم الكتاب يعرفونه كما يعرفون أبناءهم الذين خسروا أنفسهم فهم لا يؤمنون»: علماءُ أهل الكتاب يعرفون صدقَ محمدٍ ونبوّتَه معرفةً يقينيّةً كمعرفتهم أبناءهم (لما عندهم من صفته)؛ لكنّ الذين خسروا أنفسهم بالعناد لا يؤمنون. فالمعرفةُ وحدها لا تنفع بلا إذعان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يقود العلمُ إلى الإذعان لا العناد."},"action":{"text":"لا يكفي أن تعرف الحقّ، بل أذعِن له واعمل، فالمعرفةُ بلا إيمانٍ خسارة."}},{"n":21,"reflection":{"text":"«ومن أظلم ممن افترى على الله كذبا أو كذب بآياته إنه لا يفلح الظالمون»: لا أحدَ أظلمُ ممّن اختلق على الله كذبًا (كنسبة الشريك والولد) أو كذّب بآياته الحقّ؛ إنّه لا يفوز الظالمون بمطلوبهم؛ فجمعوا بين الافتراء والتكذيب. فالكذبُ على الله والتكذيبُ به قمّةُ الظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الكذبِ على الله والتكذيبِ بآياته."},"action":{"text":"لا تقُل على الله ما لا تعلم، ولا تكذّب بحقٍّ ثبت، فذاك أظلمُ الظلم."}},{"n":22,"reflection":{"text":"«ويوم نحشرهم جميعا ثم نقول للذين أشركوا أين شركاؤكم الذين كنتم تزعمون»، ويومَ نجمع الخلقَ جميعًا نقول توبيخًا للمشركين: أين آلهتُكم الذين زعمتم أنّهم شركاء وشفعاء؟ فلا يجدون منهم نصيرًا؛ ينكشف بطلانُ ما عبدوا. فالشركاءُ المزعومون يتخلّون عن عابديهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ ما عُبد دون الله يخذل يوم القيامة."},"action":{"text":"لا تعلّق رجاءك بغير الله، فكلُّ معبودٍ سواه يتخلّى عن صاحبه يومَ الحشر."}},{"n":23,"reflection":{"text":"«ثم لم تكن فتنتهم إلا أن قالوا والله ربنا ما كنا مشركين»: ثمّ لا يكون جوابُهم واعتذارُهم إلا أن يحلفوا كذبًا: والله ربّنا ما كنّا مشركين؛ يجحدون شركهم فرارًا من العقوبة، فيكذبون في موقفٍ لا ينفع فيه الكذب. فمن اعتاد الكذبَ كذب حتى على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ مع الله، فالكذبُ لا ينفع يومَ القيامة."},"action":{"text":"تعوّد الصدقَ في الدنيا، فمن كذب فيها كذب يومَ القيامة حيث لا ينفع."}},{"n":24,"reflection":{"text":"«انظر كيف كذبوا على أنفسهم وضل عنهم ما كانوا يفترون»: انظر كيف كذبوا على أنفسهم بجحد شركهم، وغاب عنهم ما كانوا يختلقونه من الشركاء والشفعاء فلم ينفعهم؛ فافتضح كذبُهم وبطل افتراؤهم. فالباطلُ يزول وينكشف يومَ الحقيقة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الباطلَ يزول وينكشف."},"action":{"text":"ابنِ أمرك على الحقّ لا على الافتراء، فالباطلُ يضلّ عن صاحبه ويفتضح."}},{"n":25,"reflection":{"text":"«ومنهم من يستمع إليك وجعلنا على قلوبهم أكنة أن يفقهوه وفي آذانهم وقرا وإن يروا كل آية لا يؤمنوا بها حتى إذا جاءوك يجادلونك يقول الذين كفروا إن هذا إلا أساطير الأولين»: منهم من يستمع لك بأذنه لا بقلبه؛ فبإعراضهم جُعل على قلوبهم أغطيةٌ تمنع الفهم وفي آذانهم صممٌ عن القبول؛ فلو رأوا كلَّ آيةٍ لم يؤمنوا، ويجادلونك زاعمين أنّ القرآن أباطيرُ الأقدمين؛ فالاستماعُ بلا قصدِ اهتداءٍ لا ينفع. فالسماعُ النافعُ ما واطأه القلب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستماعُ للقرآن بقلبٍ مقبلٍ لا معرض."},"action":{"text":"استمع للقرآن بقلبٍ يريد الهدى، فالسماعُ بلا إقبالِ قلبٍ لا يُفقِه."}}]},{"title":"حسرةُ المكذّبين عند النار، وخسّةُ الدنيا","range":[26,32],"theme":"تمنّي الكافرين الرجوعَ، وندمُ من فرّط، وأنّ الآخرةَ خيرٌ للمتّقين","verses":[{"n":26,"reflection":{"text":"«وهم ينهون عنه وينأون عنه وإن يهلكون إلا أنفسهم وما يشعرون»: ينهَون الناسَ عن اتّباع النبيّ ويبتعدون هم عنه؛ فيجمعون بين الضلال والإضلال؛ وما يُهلكون بذلك إلا أنفسهم وهم لا يشعرون بعاقبة صنيعهم. فالصادُّ عن الحقّ يهلك نفسه أوّلًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الصدِّ عن الحقّ والبعدِ عنه."},"action":{"text":"لا تصدّ أحدًا عن الحقّ ولا تبتعد عنه، فالصادُّ يهلك نفسه."}},{"n":27,"reflection":{"text":"«ولو ترى إذ وقفوا على النار فقالوا يا ليتنا نرد ولا نكذب بآيات ربنا ونكون من المؤمنين»: لو ترى حالهم إذ عُرضوا على النار فتمنّوا الرجوعَ ليؤمنوا ولا يكذّبوا؛ لرأيت أمرًا عظيمًا؛ لكنّه تمنٍّ بعد فوات الأوان. فبادر بالإيمان قبل أن تتمنّى الرجوعَ ولا رجوع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمان قبل أن يُتمنّى الرجوع."},"action":{"text":"آمن واعمل الآن، فأهلُ النار يتمنّون الرجوعَ ولا يُجابون."}},{"n":28,"reflection":{"text":"«بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وإنهم لكاذبون»: بل ظهر لهم ما كانوا يُخفون من كفرهم ونفاقهم؛ ولو رُدّوا إلى الدنيا لعادوا لما نُهوا عنه، فتمنّيهم غيرُ صادق، وإنّهم لكاذبون في وعدهم. فالطبعُ لا يتغيّر بمجرّد رؤية العاقبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"صدقُ العزمِ على التوبة لا مجرّدُ التمنّي."},"action":{"text":"اصدق في توبتك وعزمك الآن، فالتمنّي بلا صدقٍ لا يغيّر النفس."}},{"n":29,"reflection":{"text":"«وقالوا إن هي إلا حياتنا الدنيا وما نحن بمبعوثين»: كانوا يقولون منكرين البعث: ما هي إلا هذه الحياة الدنيا نموت فيها ولا نُبعث؛ فأنكروا الآخرة فجرّهم ذلك إلى الكفر والفجور. فإنكارُ البعث أصلُ الفجور.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ الرادعُ عن الفجور."},"action":{"text":"أيقِن بالبعث والحساب، فإنكارُه بابُ الغفلة والفجور."}},{"n":30,"reflection":{"text":"«ولو ترى إذ وقفوا على ربهم قال أليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون»: لو تراهم حين يُوقَفون بين يدي ربّهم فيقول: أليس هذا البعثُ حقًّا؟ فيقرّون: بلى وربّنا؛ فيقال: ذوقوا العذابَ بكفركم؛ فأقرّوا حين لا ينفع الإقرار. فالحقُّ يُقَرُّ به يومًا ولو بعد جحود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بالحقّ الآن حيث ينفع الإقرار."},"action":{"text":"أقرَّ بالحقّ واعمل به اليوم، فالمكذّبون يُقرّون به يومَ لا ينفعهم."}},{"n":31,"reflection":{"text":"«قد خسر الذين كذبوا بلقاء الله حتى إذا جاءتهم الساعة بغتة قالوا يا حسرتنا على ما فرطنا فيها وهم يحملون أوزارهم على ظهورهم ألا ساء ما يزرون»: خسر المكذّبون بلقاء الله والبعث، حتى إذا فاجأتهم الساعةُ تحسّروا على تفريطهم، وهم يحملون آثامهم أثقالًا على ظهورهم؛ بئس ما يحملون. فالتفريطُ في العمل حسرةٌ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التفريطِ الذي يورث الحسرة."},"action":{"text":"لا تفرّط في عملك للآخرة، فالمفرّطون يتحسّرون يومَ تُفاجئهم الساعة."}},{"n":32,"reflection":{"text":"«وما الحياة الدنيا إلا لعب ولهو وللدار الآخرة خير للذين يتقون أفلا تعقلون»: ليست الدنيا في جنب الآخرة إلا لعبًا يشغل ولهوًا يُلهي عن الحقّ؛ والدارُ الآخرةُ خيرٌ وأبقى للمتّقين؛ أفلا تعقلون فتؤثرون الباقيَ على الفاني؟ فالعاقلُ يعمل للباقية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ الآخرةِ الباقيةِ على الدنيا اللاهية."},"action":{"text":"لا تجعل الدنيا أكبرَ همّك، فهي لعبٌ ولهو، والآخرةُ خيرٌ للمتّقين."}}]},{"title":"تسليةُ النبي، وأنّ المستجيبَ من يسمع","range":[33,36],"theme":"عزاءُ النبي عن جحود قومه، وصبرُ الرسل حتى النصر، وأنّ المنتفعَ من يُصغي بقلبه","verses":[{"n":33,"reflection":{"text":"«قد نعلم إنه ليحزنك الذي يقولون فإنهم لا يكذبونك ولكن الظالمين بآيات الله يجحدون»: نعلم أنّ تكذيبهم يحزنك يا محمد؛ لكنّهم في قرارة أنفسهم لا يكذّبونك، فهم يعرفون صدقك، وإنّما يجحدون آياتِ الله عنادًا وظلمًا؛ فالتكذيبُ لله لا لك في الحقيقة. فتكذيبُ الظالمين للحقّ جحودٌ لا شكّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسلّي بأنّ ردَّ الحقّ جحودٌ لا تكذيبٌ لك."},"action":{"text":"لا يحزنك ردُّ الناس للحقّ، فهم يجحدون آياتِ الله عنادًا لا لشكٍّ فيك."}},{"n":34,"reflection":{"text":"«ولقد كذبت رسل من قبلك فصبروا على ما كذبوا وأوذوا حتى أتاهم نصرنا ولا مبدل لكلمات الله ولقد جاءك من نبإ المرسلين»: قد كُذّب رسلٌ قبلك فصبروا على التكذيب والأذى حتى جاءهم نصرُ الله؛ ولا مغيّرَ لوعده بنصر رسله؛ وقد جاءك من أخبارهم ما يثبّتك؛ فاصبر كما صبروا يأتك النصر. فالصبرُ سبيلُ النصر، ووعدُ الله لا يتبدّل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى ثقةً بوعدِ الله بالنصر."},"action":{"text":"اصبر على أذى الحقّ كما صبر الرسل، فوعدُ الله بالنصر لا يتبدّل."}},{"n":35,"reflection":{"text":"«وإن كان كبر عليك إعراضهم فإن استطعت أن تبتغي نفقا في الأرض أو سلما في السماء فتأتيهم بآية ولو شاء الله لجمعهم على الهدى فلا تكونن من الجاهلين»: إن شقّ عليك إعراضُهم فلن تُكرههم على الإيمان ولو استطعت أن تنفذ في الأرض أو تصعد إلى السماء لتأتيهم بآية؛ ولو شاء الله لجمعهم على الهدى، لكنّه ابتلاء؛ فسلِّم لحكمته ولا تحمل همًّا لا يُطاق. فالهدايةُ بيد الله لا بيدك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله في الهداية وطرحُ الحرص المفرط."},"action":{"text":"بلّغ ولا تحمل همَّ من أعرض فوق طاقتك، فالهدايةُ بيد الله وحده."}},{"n":36,"reflection":{"text":"«إنما يستجيب الذين يسمعون والموتى يبعثهم الله ثم إليه يرجعون»: إنّما ينتفع بدعوتك ويستجيب أحياءُ القلوب الذين يسمعون سماعَ قبولٍ؛ وأمّا موتى القلوب (كالكفار) فهم كالأموات لا يسمعون، والله يبعث الأمواتَ يومَ القيامة ثمّ إليه المرجع فيجازيهم. فالمنتفعُ من كان حيَّ القلب مصغيًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ حياةِ القلبِ لسماعِ الحقّ والانتفاعِ به."},"action":{"text":"أحيِ قلبك بالإقبال على الحقّ، فالمنتفعُ من يسمع بقلبٍ حيٍّ لا ميّت."}}]},{"title":"الدوابُّ أممٌ أمثالكم، وكشفُ الضرّ بيده","range":[37,41],"theme":"شمولُ علمِ الله بكلّ خلقه، وأنّ المكذّبين صمٌّ بكم، وأنّ الملتجأَ عند الشدّة هو الله وحده","verses":[{"n":37,"reflection":{"text":"«وقالوا لولا نزل عليه آية من ربه قل إن الله قادر على أن ينزل آية ولكن أكثرهم لا يعلمون»: اقترحوا آيةً حسّيّةً من ربّه (كناقة صالح)؛ قل: الله قادرٌ على إنزالها، لكن حكمتَه اقتضت غيرَ ذلك، ولو أُنزلت فكذّبوا لعُوجِّلوا بالهلاك؛ وأكثرهم لا يعلمون حكمةَ الله. فمنعُ ما اقترحوه رحمةٌ وحكمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله في تدبيره وآياته."},"action":{"text":"لا تقترح على الله، فقدرتُه لا تُحدّ، وحكمتُه في المنع كما في العطاء."}},{"n":38,"reflection":{"text":"«وما من دابة في الأرض ولا طائر يطير بجناحيه إلا أمم أمثالكم ما فرطنا في الكتاب من شيء ثم إلى ربهم يحشرون»: كلُّ دابّةٍ في الأرض وكلُّ طائرٍ أممٌ أمثالكم في الخلق والرزق والتدبير، يعلمها الله ويرزقها؛ وما تركنا في اللوح المحفوظ (أو القرآن) شيئًا من علم مصالحهم؛ ثمّ تُحشر كلُّها إلى ربّها. فعلمُ الله وتدبيرُه يسع كلَّ مخلوق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ إحاطةِ الله برزقِ كلِّ دابّة وتدبيرِها."},"action":{"text":"تأمّل عنايةَ الله بكلّ دابّةٍ وطائر، واطمئن أنّ رزقك عليه ومصيرك إليه."}},{"n":39,"reflection":{"text":"«والذين كذبوا بآياتنا صم وبكم في الظلمات من يشإ الله يضلله ومن يشأ يجعله على صراط مستقيم»: المكذّبون بآياتنا كالصمّ لا يسمعون الحقَّ، والبكم لا ينطقون به، غارقون في ظلمات الجهل والكفر؛ ومشيئةُ الله نافذة: من يشأ يضلّه بعدله، ومن يشأ يهديه بفضله؛ فاطلب الهدايةَ من مالكها. فالهدايةُ والإضلالُ بيد الله وفق حكمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله واجتنابُ أسبابِ الإضلال."},"action":{"text":"اسأل الله الهدايةَ إلى صراطه المستقيم، واجتنب ما يُصمّ القلبَ عن الحق."}},{"n":40,"reflection":{"text":"«قل أرأيتكم إن أتاكم عذاب الله أو أتتكم الساعة أغير الله تدعون إن كنتم صادقين»: قل لهم: أخبروني، إن نزل بكم عذابُ الله أو قامت الساعةُ، أتدعون غيرَ الله لكشفه إن كنتم صادقين في اتّخاذ الشركاء؟ لا، بل تلجؤون إليه وحده؛ فلِمَ تعبدون سواه في الرخاء؟ ففطرةُ اللجوء لله تنكشف عند الشدّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله وحده في الرخاء كما في الشدّة."},"action":{"text":"الجأ إلى الله وحده دائمًا، فأنت لا تدعو سواه حين ينزل بك الكرب."}},{"n":41,"reflection":{"text":"«بل إياه تدعون فيكشف ما تدعون إليه إن شاء وتنسون ما تشركون»: بل تدعون الله وحده عند الشدّة فيكشف ضرّكم إن شاء بحكمته، وتنسون آلهتكم التي كنتم تشركونها؛ فدلّ اضطرارُكم إليه على أنّه المعبودُ الحقّ. فالشدائدُ تُرجع القلبَ إلى فطرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ لله المُجيبِ عند الاضطرار."},"action":{"text":"أخلص دعاءك لله الذي يكشف ضرّك، ولا تشرك به من لا يملك لك شيئًا."}}]},{"title":"سنّةُ البأساء والاستدراج، وقطعُ دابرِ الظالمين","range":[42,45],"theme":"الابتلاءُ للتضرّع، وقسوةُ القلب تمنعه، والاستدراجُ بالنعم ثمّ الأخذُ بغتة","verses":[{"n":42,"reflection":{"text":"«ولقد أرسلنا إلى أمم من قبلك فأخذناهم بالبأساء والضراء لعلهم يتضرعون»: أرسلنا رسلًا إلى أممٍ قبلك فكذّبوا، فابتليناهم بالفقر والشدّة والمرض لعلّهم يخضعون ويتضرّعون إلى الله فيرجعوا؛ فالبلاءُ رسالةٌ تدعو للرجوع. فالشدائدُ تُساق ليتذكّر الغافل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التضرّعُ إلى الله عند البلاء والرجوعُ إليه."},"action":{"text":"إذا أصابك بلاءٌ فتضرّع إلى الله وارجع إليه، فالبلاءُ يدعوك إليه."}},{"n":43,"reflection":{"text":"«فلولا إذ جاءهم بأسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطان ما كانوا يعملون»: فهلّا تضرّعوا حين نزل بهم عذابنا؟ لكنّ قلوبهم قست فلم تلن، وزيّن لهم الشيطانُ كفرَهم ومعاصيهم فأصرّوا؛ فقسوةُ القلب تمنع الاتّعاظ. فالإصرارُ مع البلاء علامةُ قسوةِ القلب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قسوةِ القلبِ التي تمنع التضرّع."},"action":{"text":"لن قلبك للحقّ عند البلاء، واحذر قسوةً تمنعك من الرجوع إلى الله."}},{"n":44,"reflection":{"text":"«فلما نسوا ما ذكروا به فتحنا عليهم أبواب كل شيء حتى إذا فرحوا بما أوتوا أخذناهم بغتة فإذا هم مبلسون»: فلمّا أعرضوا وتركوا ما ذُكّروا به، فتحنا عليهم أبوابَ الرزق والنعم استدراجًا لا كرامةً، حتى إذا فرحوا واغترّوا أخذناهم فجأةً بالعذاب فإذا هم آيسون متحيّرون؛ فالنعمةُ مع المعصية قد تكون استدراجًا. فاحذر أن تُفتح لك الأبوابُ وأنت مصرّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من استدراجِ النعمِ مع الإصرار على المعصية."},"action":{"text":"لا تغترّ بسعةِ الرزق مع المعصية، فقد تكون استدراجًا يعقبه أخذٌ بغتة."}},{"n":45,"reflection":{"text":"«فقطع دابر القوم الذين ظلموا والحمد لله رب العالمين»: فاستُؤصل آخرُ الظالمين حتى لم يبقَ منهم أحد؛ والحمدُ لله ربّ العالمين على هلاك الظالمين ونجاةِ المؤمنين، فهو حمدٌ على عدله كما يُحمد على فضله. فعاقبةُ الظلمِ الاستئصال، والحمدُ لله على عدله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حمدُ الله على عدلِه في إهلاك الظالمين."},"action":{"text":"احمد الله على عدله كما تحمده على فضله، واعلم أنّ عاقبةَ الظلم البتر."}}]},{"title":"من يردّ سمعك وبصرك؟ ومهمّةُ الرسل","range":[46,51],"theme":"انفرادُ الله بالنعم والعقوبة، والرسلُ مبشّرون ومنذرون، وتواضعُ النبي وصدقُه","verses":[{"n":46,"reflection":{"text":"«قل أرأيتم إن أخذ الله سمعكم وأبصاركم وختم على قلوبكم من إله غير الله يأتيكم به انظر كيف نصرف الآيات ثم هم يصدفون»: قل: أخبروني، لو سلبكم الله سمعكم وأبصاركم وطبع على قلوبكم، أيّ إلهٍ غيره يردّها إليكم؟ لا أحد؛ انظر كيف نبيّن الآياتِ بأنواعها ثمّ هم يُعرضون؛ فالنعمُ منه وحده، فكيف يُعبد سواه؟ فمن يملك حواسّك هو المستحقُّ للعبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ السمعِ والبصرِ والقلبِ لواهبها."},"action":{"text":"اشكر الله على سمعك وبصرك وقلبك، واستعملها في طاعته، فهو واهبُها."}},{"n":47,"reflection":{"text":"«قل أرأيتكم إن أتاكم عذاب الله بغتة أو جهرة هل يهلك إلا القوم الظالمون»: قل: إن جاءكم عذابُ الله فجأةً أو معلنًا، هل يُهلَك بالعذاب إلا الظالمون المكذّبون؟ فالعقوبةُ عدلٌ تحلّ بأهل الظلم؛ فاحذروا الظلمَ الذي يجلبها. فالنجاةُ بترك الظلم والكفر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الظلمِ الجالبِ للعذاب."},"action":{"text":"اجتنب الظلمَ والكفر، فالعذابُ لا يحلّ إلا بالظالمين."}},{"n":48,"reflection":{"text":"«وما نرسل المرسلين إلا مبشرين ومنذرين فمن آمن وأصلح فلا خوف عليهم ولا هم يحزنون»: ما أرسلنا الرسلَ إلا ليبشّروا المطيعين ويُنذروا العاصين؛ فمن آمن وأصلح عملَه فلا خوفٌ عليهم فيما يستقبلون ولا حزنٌ على ما فات؛ فأمنُ الآخرة للمؤمن المصلح. فالإيمانُ والإصلاحُ أمانٌ وطمأنينة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والإصلاحِ لنيلِ الأمن."},"action":{"text":"آمن وأصلح عملك، فبهما يأمن القلبُ فلا خوفٌ ولا حزن."}},{"n":49,"reflection":{"text":"«والذين كذبوا بآياتنا يمسهم العذاب بما كانوا يفسقون»، والذين كذّبوا بآيات الله يصيبهم العذابُ بسبب خروجهم عن طاعته وإصرارهم على الفسق؛ فالجزاءُ من جنس العمل. فالتكذيبُ والفسوقُ يجلبان العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التكذيبِ والفسوقِ الجالبَين للعذاب."},"action":{"text":"صدّق بآيات الله والزم طاعته، فالتكذيبُ والفسقُ سببُ العذاب."}},{"n":50,"reflection":{"text":"«قل لا أقول لكم عندي خزائن الله ولا أعلم الغيب ولا أقول لكم إني ملك إن أتبع إلا ما يوحى إلي قل هل يستوي الأعمى والبصير أفلا تتفكرون»: قل متواضعًا: لا أدّعي ملكَ خزائن الله، ولا علمَ الغيب، ولا أنّي ملَك؛ إنّما أتّبع الوحيَ فأبلّغه؛ ثمّ قل: هل يستوي الأعمى (الكافر) والبصير (المؤمن)؟ أفلا تتفكّرون فتختاروا البصيرة؟ فصدقُ النبي في تواضعه وحصرِ دعواه في البلاغ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ وحصرُ الدعوى في اتّباعِ الوحي."},"action":{"text":"لا تدّعِ ما ليس لك، واتّبع الوحيَ، فالبصيرةُ في الإيمان لا في العمى."}},{"n":51,"reflection":{"text":"«وأنذر به الذين يخافون أن يحشروا إلى ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون»: أنذر بالقرآن الذين يخافون البعثَ والحشرَ إلى ربّهم، الذين يعلمون أنّه لا وليَّ لهم ولا شفيعَ سواه؛ فهؤلاء ينتفعون بالإنذار لعلّهم يتّقون؛ فالإنذارُ ينفع خائفَ القلب. فالمنتفعُ بالتذكير من يخاف لقاء الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ الحشرِ وأنّه لا وليَّ ولا شفيعَ سوى الله."},"action":{"text":"اعمل بخوف لقاء الله، فلا وليَّ لك ولا شفيعَ يومئذٍ إلا هو."}}]},{"title":"لا تطرد الضعفاء، ورحمةُ الله بالمؤمنين","range":[52,55],"theme":"تكريمُ الفقراء المخلصين، وأنّ الفتنةَ بالتفاوت اختبار، وسلامُ الله على المؤمنين","verses":[{"n":52,"reflection":{"text":"«ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظالمين»: لا تُبعِد الفقراءَ المخلصين (كبلالٍ وصهيبٍ وعمّار) الذين يعبدون ربّهم صباحًا ومساءً مريدين وجهه، إرضاءً لكبراء المشركين؛ فلست محاسبًا على نيّاتهم ولا هم على نيّتك؛ فطردُهم ظلم. فلا تُقدّم وجيهًا كافرًا على فقيرٍ مؤمن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تكريمُ المؤمن الفقير وعدمُ ازدرائه."},"action":{"text":"أكرِم أهلَ الإيمان ولو كانوا فقراء، ولا تُقصِهم إرضاءً لوجيهٍ أو غنيّ."}},{"n":53,"reflection":{"text":"«وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين»، وهكذا اختبرنا الناسَ بعضهم ببعض (الغنيَّ بالفقير، والشريفَ بالوضيع) حتى يقول المتكبّرون مستنكرين: أهؤلاء الضعفاءُ منّ الله عليهم بالإيمان دوننا؟ أليس الله أعلمَ بمن يشكر نعمته فيهديه؟ فالله يهدي من علم منه الشكرَ لا من زعم الشرف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ كرامةَ الله لأهل الشكر لا للجاه."},"action":{"text":"لا تحتقر مؤمنًا لضعفه، فالله يهدي الشاكرين وإن ازدراهم المتكبّرون."}},{"n":54,"reflection":{"text":"«وإذا جاءك الذين يؤمنون بآياتنا فقل سلام عليكم كتب ربكم على نفسه الرحمة أنه من عمل منكم سوءا بجهالة ثم تاب من بعده وأصلح فأنه غفور رحيم»: إذا جاءك المؤمنون فابدأهم بالسلام وبشّرهم بسعة رحمة الله: من عمل منكم ذنبًا بجهالةٍ ثمّ تاب وأصلح فإنّ الله غفورٌ رحيم؛ فرحمتُه كتبها على نفسه لعباده التائبين. فبابُ الرحمة مفتوحٌ لمن تاب وأصلح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"الرجاءُ في رحمةِ الله لمن تاب وأصلح، ولينُ الجانب."},"action":{"text":"أبشِر برحمة الله إن تبت وأصلحت، وابدأ إخوانك بالسلام والبِشر."}},{"n":55,"reflection":{"text":"«وكذلك نفصل الآيات ولتستبين سبيل المجرمين»، وكما بيّنّا هذه الآيات نفصّل غيرها ونوضّحها ليتبيّن الحقُّ من الباطل، ولتظهر طريقُ المجرمين فتُجتنب؛ فمعرفةُ سبيل الشرّ سبيلٌ لاجتنابه. فالبيانُ يكشف طريقَ الحقّ وطريقَ الإجرام.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ سبيلِ المجرمين لاجتنابها."},"action":{"text":"اعرف طرقَ الشرّ لتجتنبها، فتفصيلُ الآيات يكشف الحقَّ ويُبيّن سبيلَ الباطل."}}]},{"title":"البيّنةُ والحكمُ لله، ومفاتحُ الغيب","range":[56,62],"theme":"البراءةُ من الشرك، وأنّ الحكمَ لله، وسعةُ علمِه بالغيب والشهادة وقبضِه للأرواح","verses":[{"n":56,"reflection":{"text":"«قل إني نهيت أن أعبد الذين تدعون من دون الله قل لا أتبع أهواءكم قد ضللت إذا وما أنا من المهتدين»: قل: نهاني الله أن أعبد ما تعبدون من دونه؛ ولن أتّبع أهواءكم في الشرك، فلو اتّبعتها لضللتُ ولم أكن من المهتدين. فاتّباعُ الهوى في الدين ضلال، والاعتصامُ بالوحي هدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"رفضُ اتّباعِ الأهواءِ في الدين ولزومُ الوحي."},"action":{"text":"لا تتّبع أهواءَ الناس في دينك، فالهدى في الوحي لا في الأهواء."}},{"n":57,"reflection":{"text":"«قل إني على بينة من ربي وكذبتم به ما عندي ما تستعجلون به إن الحكم إلا لله يقص الحق وهو خير الفاصلين»: قل: أنا على حجّةٍ واضحةٍ من ربّي، وأنتم كذّبتم بها؛ وليس عندي العذابُ الذي تستعجلونه، فأمرُه إلى الله؛ فالحكمُ لله وحده يقضي بالحقّ وهو خيرُ من يفصل بين المحقّ والمبطل. فالحكمُ والعذابُ بيد الله في وقته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ بأنّ الحكمَ لله وحده في وقته وحكمته."},"action":{"text":"سلّم الأمرَ لله، فالحكمُ له وحده، يقضي بالحقّ في الوقت الذي يشاء."}},{"n":58,"reflection":{"text":"«قل لو أن عندي ما تستعجلون به لقضي الأمر بيني وبينكم والله أعلم بالظالمين»: قل: لو كان بيدي العذابُ الذي تستعجلونه لأنزلته بكم فانتهى الأمرُ بيننا؛ لكنّه بيد الله وهو أعلمُ بالظالمين ومتى يأخذهم بحكمته. فتأخيرُ العقوبة حكمةٌ لا عجز.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بحكمة الله في تأخيرِ العقوبة."},"action":{"text":"لا تستعجل قضاءَ الله، فتأخيرُ العقوبة حكمةٌ، وهو أعلمُ بالظالمين."}},{"n":59,"reflection":{"text":"«وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين»: عند الله وحده خزائنُ الغيب لا يعلمها سواه؛ يعلم كلَّ ما في البرّ والبحر، وما تسقط ورقةٌ من شجرةٍ إلا بعلمه، ولا حبّةٌ في باطن الأرض، ولا رطبٌ ولا يابسٌ إلا وهو مثبتٌ في اللوح المحفوظ؛ فعلمُه محيطٌ بأدقّ الأشياء. فمن أحاط علمُه بكلّ شيءٍ يُراقَب في كلّ شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عالم الغيب"],"heart_state":{"text":"استحضارُ إحاطةِ علمِ الله بأدقّ التفاصيل."},"action":{"text":"راقب اللهَ الذي يعلم سقوطَ الورقة والحبّةَ في الظلمة، فلا يخفى عليه شيءٌ منك."}},{"n":60,"reflection":{"text":"«وهو الذي يتوفاكم بالليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى أجل مسمى ثم إليه مرجعكم ثم ينبئكم بما كنتم تعملون»: هو الذي يقبض أرواحكم في النوم بالليل (وفاةً صغرى) ويعلم ما كسبتم بالنهار، ثمّ يوقظكم في النهار لتكملوا أعماركم؛ ثمّ إليه المرجعُ بالموت، فيخبركم بأعمالكم ويجازيكم. فالنومُ واليقظةُ آيةُ الموت والبعث كلَّ يوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالنومِ والاستيقاظِ آيةَ الموت والبعث."},"action":{"text":"تذكّر بنومك واستيقاظك موتَك وبعثك، واستعدّ ليومٍ تُنبَّأ فيه بعملك."}},{"n":61,"reflection":{"text":"«وهو القاهر فوق عباده ويرسل عليكم حفظة حتى إذا جاء أحدكم الموت توفته رسلنا وهم لا يفرطون»: هو الغالبُ فوق عباده، يرسل عليكم ملائكةً يحفظون أعمالكم ويحصونها، حتى إذا حضر أحدَكم الموتُ قبضت روحَه ملائكةُ الموت بلا تقصيرٍ ولا تأخير؛ فالأعمالُ محفوظة، والأجلُ محتوم. فكلُّ عملٍ محصًى، وكلُّ نفسٍ مقبوضةٌ بأجلها.","source":"تفسير السعدي","grade":"ma'thur"},"names":["القاهر"],"heart_state":{"text":"استحضارُ حفظِ الأعمالِ وحتميّةِ قبض الروح."},"action":{"text":"اعلم أنّ عملك محفوظٌ وأجلك محتوم، فاعمل صالحًا قبل أن تقبض روحك."}},{"n":62,"reflection":{"text":"«ثم ردوا إلى الله مولاهم الحق ألا له الحكم وهو أسرع الحاسبين»: ثمّ يُرَدّ العبادُ بعد الموت إلى الله سيّدهم الحقّ؛ ألا له وحده الحكمُ والقضاءُ يومَ القيامة، وهو أسرعُ الحاسبين يحاسب الخلقَ كلَّهم في لحظة؛ فلا مفرّ من حكمه. فالمرجعُ إلى الله، والحكمُ له، والحسابُ سريع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المولى","أسرع الحاسبين"],"heart_state":{"text":"الاستعدادُ للردّ إلى الله وسرعةِ حسابه."},"action":{"text":"استعدّ للقاء الله مولاك الحقّ، فإليه المرجع، وهو أسرعُ الحاسبين."}}]},{"title":"الله ينجّيكم من كلّ كرب، وقدرتُه على العذاب","range":[63,67],"theme":"إخلاصُ الدعاءِ عند الكرب لله، ونقضُ الشركِ بعد النجاة، وقدرةُ الله على أنواع العذاب","verses":[{"n":63,"reflection":{"text":"«قل من ينجيكم من ظلمات البر والبحر تدعونه تضرعا وخفية لئن أنجانا من هذه لنكونن من الشاكرين»: قل: من ينقذكم من شدائد البرّ والبحر حين تدعونه متضرّعين سرًّا وعلانيةً، وتعاهدونه: لئن أنجيتنا لنشكرنّك؟ إنّه الله وحده. فعند الشدّة تخلص القلوبُ لله وتعاهد على الشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ لله عند الشدائد والوفاءُ بالشكر."},"action":{"text":"إذا اشتدّ بك الكرب فادعُ الله وحده، وأوفِ بما عاهدته عليه من الشكر."}},{"n":64,"reflection":{"text":"«قل الله ينجيكم منها ومن كل كرب ثم أنتم تشركون»: قل: الله وحده ينجّيكم من تلك الشدّة ومن كلّ همٍّ وكرب؛ ثمّ أنتم، بعد النجاة، تعودون إلى الشرك وتنسون فضله! فما أعظمَ جحودَ من نجّاه الله ثمّ أشرك به. فالوفاءُ لله بعد النجاة توحيدٌ وشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ لله بعد النجاة وعدمُ العودةِ للغفلة."},"action":{"text":"إذا نجّاك الله من كربٍ فلا تعُد إلى الغفلة والذنب، بل ازدد له شكرًا وتوحيدًا."}},{"n":65,"reflection":{"text":"«قل هو القادر على أن يبعث عليكم عذابا من فوقكم أو من تحت أرجلكم أو يلبسكم شيعا ويذيق بعضكم بأس بعض انظر كيف نصرف الآيات لعلهم يفقهون»: قل: الله قادرٌ أن يرسل عليكم عذابًا من فوقكم (كالصواعق) أو من تحتكم (كالخسف)، أو يجعلكم فرقًا متناحرةً يذيق بعضُكم بأسَ بعض؛ انظر كيف نصرّف الآياتِ لعلّهم يفهمون؛ (وقد استعاذ النبيُّ ﷺ من الأوّلين فأُعيذ، وسأل ألّا يجعل بأسهم بينهم فمُنع). فاختلافُ الأمّة عذابٌ نسأل الله العافية منه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعاذةُ من العذاب ومن الفرقةِ والاقتتال."},"action":{"text":"اسأل الله العافيةَ من العذاب ومن فرقة الأمّة، واسعَ في جمع الكلمة لا تفريقها."}},{"n":66,"reflection":{"text":"«وكذب به قومك وهو الحق قل لست عليكم بوكيل»، وكذّب قومُك يا محمد بالقرآن وهو الحقُّ الذي لا شكّ فيه؛ قل: لست موكّلًا بحفظكم وإجباركم على الإيمان، إنّما أنا مبلّغ؛ فالحسابُ على الله. فمهمّةُ الداعي البلاغ، والهدايةُ على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ البلاغ وتركُ الهداية لله."},"action":{"text":"بلّغ الحقّ ولا تحمل همّ إجبار الناس، فلست وكيلًا عليهم بل مبلّغًا."}},{"n":67,"reflection":{"text":"«لكل نبإ مستقر وسوف تعلمون»: لكلّ خبرٍ أخبر الله به وقتٌ يستقرّ فيه ويقع لا محالة؛ وسوف تعلمون صدقَ ما أُخبرتم به من الوعد والوعيد حين يقع. فوعدُ الله وخبرُه واقعٌ في وقته المقدّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ خبرَ الله واقعٌ في وقته."},"action":{"text":"صدّق بوعد الله ووعيده، فكلُّ خبرٍ منه له وقتٌ يقع فيه لا محالة."}}]},{"title":"الإعراضُ عن الخائضين، وتذكيرٌ بالحساب","range":[68,73],"theme":"هجرُ مجالسِ الاستهزاء بالآيات، وأنّ لا شفيعَ يوم القيامة، وعظمةُ الخالقِ صاحبِ الملك","verses":[{"n":68,"reflection":{"text":"«وإذا رأيت الذين يخوضون في آياتنا فأعرض عنهم حتى يخوضوا في حديث غيره وإما ينسينك الشيطان فلا تقعد بعد الذكرى مع القوم الظالمين»: إذا رأيت من يخوضون في آيات الله بالاستهزاء والتكذيب فأعرض عنهم حتى يتحوّلوا إلى حديثٍ آخر؛ فإن أنساك الشيطانُ فقعدت فلا تستمرّ بعد التذكّر مع الظالمين. فمجالسُ الاستهزاء بالدين تُهجَر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"هجرُ مجالسِ الخوضِ في آيات الله بالباطل."},"action":{"text":"إذا سمعت استهزاءً بآيات الله في مجلسٍ فقُم عنه، ولا تستمرّ بعد التذكّر."}},{"n":69,"reflection":{"text":"«وما على الذين يتقون من حسابهم من شيء ولكن ذكرى لعلهم يتقون»: ليس على المتّقين إثمٌ من حساب الخائضين إذا جالسوهم للتذكير والنصح لا للرضا؛ لكن عليهم أن يذكّروهم لعلّهم يتّقون ويكفّون؛ فالمجالسةُ للاحتساب لا للإقرار. فالمقصودُ التذكيرُ لا الرضا بالمنكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المجالسةُ للتذكير والنصحِ لا للرضا بالباطل."},"action":{"text":"إن خالطت مخطئًا فلتذكيره ونصحه، لا لإقراره على باطله."}},{"n":70,"reflection":{"text":"«وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياة الدنيا وذكر به أن تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع... لهم شراب من حميم وعذاب أليم بما كانوا يكفرون»: اترك الذين جعلوا دينهم لهوًا وخدعتهم الدنيا؛ وذكّر بالقرآن لئلّا تُسلَم نفسٌ للهلاك بذنبها، فليس لها وليٌّ ولا شفيعٌ سوى الله، ولو بذلت كلَّ فداءٍ لم يُقبل؛ أولئك أُسلموا للعذاب: لهم شرابٌ من ماءٍ حارٍّ وعذابٌ أليم بكفرهم. فلا فداءَ ولا شفيعَ يومئذٍ إلا بإذن الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ قبل يومٍ لا وليَّ فيه ولا شفيعَ ولا فداء."},"action":{"text":"اعمل لنجاة نفسك، فلا يفديها مالٌ ولا شفيعٌ يومَ القيامة إلا رحمةُ الله."}},{"n":71,"reflection":{"text":"«قل أندعو من دون الله ما لا ينفعنا ولا يضرنا ونرد على أعقابنا بعد إذ هدانا الله كالذي استهوته الشياطين في الأرض حيران له أصحاب يدعونه إلى الهدى ائتنا قل إن هدى الله هو الهدى وأمرنا لنسلم لرب العالمين»: قل: أنعبد ما لا ينفع ولا يضرّ، ونرجع كفّارًا بعد أن هدانا الله؟ فنكون كمن أضلّته الشياطين في مهامه الأرض حيران، وأصحابُه على الطريق ينادونه أن ارجع إلينا وهو لا يستجيب؛ قل: هدى الله هو الهدى الحقّ، وأُمرنا أن نُسلم لربّ العالمين. فالرجوعُ عن الهدى بعد معرفته حيرةٌ وهلاك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على هدى الله بعد معرفتِه."},"action":{"text":"اثبت على الهدى بعد أن منّ الله به عليك، ولا ترجع إلى ضلالٍ بعد نور."}},{"n":72,"reflection":{"text":"«وأن أقيموا الصلاة واتقوه وهو الذي إليه تحشرون»، وأُمرنا أن نقيم الصلاة تامّةً ونتّقي الله في كلّ أمرنا؛ وهو الذي إليه تُجمعون يومَ القيامة للحساب؛ فأقيموا الصلاةَ استعدادًا للقائه. فالصلاةُ والتقوى زادُ يوم الحشر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ الصلاةِ والتقوى استعدادًا للحشر."},"action":{"text":"أقم صلاتك واتّقِ الله، مستحضرًا أنّك إليه تُحشر فتُجازى."}},{"n":73,"reflection":{"text":"«وهو الذي خلق السماوات والأرض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور عالم الغيب والشهادة وهو الحكيم الخبير»: هو الذي خلق الكونَ بالحقّ لا عبثًا، وإذا أراد شيئًا قال له كن فيكون؛ قولُه الحقُّ النافذ، وله الملكُ المطلقُ يومَ ينفخ إسرافيلُ في الصور للبعث؛ عالمُ ما غاب وما حضر، الحكيمُ في خلقه، الخبيرُ بخفايا الأمور. فمن هذا شأنُه هو المعبودُ وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عالم الغيب والشهادة","الحكيم","الخبير"],"heart_state":{"text":"تعظيمُ الخالقِ صاحبِ الأمرِ النافذِ والملكِ يومَ البعث."},"action":{"text":"عظّم اللهَ الذي يقول للشيء كن فيكون، وله الملك، فأخلِص له العبادة."}}]},{"title":"حجّةُ إبراهيم: من الكوكب إلى فاطرِ السماوات","range":[74,79],"theme":"مناظرةُ إبراهيم أباه وقومه، ونظرُه في الأفول ليصل إلى توحيدِ الفاطر","verses":[{"n":74,"reflection":{"text":"«وإذ قال إبراهيم لأبيه آزر أتتخذ أصناما آلهة إني أراك وقومك في ضلال مبين»، واذكر إذ قال إبراهيمُ لأبيه آزر ناصحًا: أتعبد أصنامًا لا تنفع ولا تضرّ؟ إنّي أراك وقومك في ضلالٍ ظاهر؛ فبدأ بالنصح لأقرب الناس إليه برفقٍ وصدق. فالدعوةُ تبدأ بالأقربين برفق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"نصحُ الأقربين بالتوحيد برفقٍ وصدق."},"action":{"text":"ابدأ بدعوة أهلك وأقربيك إلى التوحيد برفقٍ وحكمة كما فعل إبراهيم."}},{"n":75,"reflection":{"text":"«وكذلك نري إبراهيم ملكوت السماوات والأرض وليكون من الموقنين»، وكما بصّرناه ضلالَ قومه، أريناه عظيمَ ملكِ الله في السماوات والأرض وبديعَ صنعه، ليزداد يقينًا ويستدلّ به على وحدانيّة الخالق؛ فالتفكّرُ في الملكوت يورث اليقين. فالنظرُ في خلق الله بابُ اليقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في ملكوت السماوات والأرض لزيادةِ اليقين."},"action":{"text":"تأمّل عظمةَ خلق الله في الكون، فالنظرُ في ملكوته يزيدك يقينًا بوحدانيّته."}},{"n":76,"reflection":{"text":"«فلما جن عليه الليل رأى كوكبا قال هذا ربي فلما أفل قال لا أحب الآفلين»: لمّا أظلم عليه الليل رأى كوكبًا لامعًا فقال، على سبيل التنزّل مع قومه ليُبطل عبادة النجوم ،: هذا ربّي؛ فلمّا غاب قال: لا أحبّ الآلهةَ التي تغيب وتزول؛ فالربُّ لا يأفل. فالمعبودُ الحقُّ لا يغيب ولا يزول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ ما يزول ويأفل لا يصلح إلهًا."},"action":{"text":"لا تعلّق قلبك بزائلٍ، فالمعبودُ الحقُّ باقٍ لا يأفل ولا يزول."}},{"n":77,"reflection":{"text":"«فلما رأى القمر بازغا قال هذا ربي فلما أفل قال لئن لم يهدني ربي لأكونن من القوم الضالين»: فلمّا رأى القمرَ طالعًا أكبرَ من الكوكب قال: هذا ربّي، فلمّا غاب قال: لئن لم يوفّقني ربّي للهدى لأكوننّ من الضالّين؛ فأظهر افتقارَه إلى هداية الله. فالهدايةُ بتوفيق الله لا بمجرّد النظر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الافتقارُ إلى الله في طلبِ الهداية."},"action":{"text":"اطلب الهدايةَ من الله وافتقر إليه، فلا يهتدي أحدٌ إلا بتوفيقه."}},{"n":78,"reflection":{"text":"«فلما رأى الشمس بازغة قال هذا ربي هذا أكبر فلما أفلت قال يا قوم إني بريء مما تشركون»: فلمّا رأى الشمسَ طالعةً أكبرَ من القمر قال: هذا ربّي هذا أكبر، فلمّا غابت أعلن نتيجةَ الحجّة: يا قوم إنّي بريءٌ من كلّ ما تشركونه بالله؛ فما دام كلُّها يأفل فلا يصلح ربًّا. فالبراءةُ من الشرك ثمرةُ النظر الصادق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البراءةُ من الشركِ بعد وضوحِ الحجّة."},"action":{"text":"تبرّأ من كلّ معبودٍ سوى الله، فالكواكبُ كلُّها آفلةٌ مخلوقةٌ لا تُعبد."}},{"n":79,"reflection":{"text":"«إني وجهت وجهي للذي فطر السماوات والأرض حنيفا وما أنا من المشركين»: أعلن إبراهيمُ توحيدَه الخالص: وجّهتُ عبادتي وقصدي للذي أبدع السماواتِ والأرضَ، مائلًا عن الشرك إلى التوحيد، ولستُ من المشركين؛ فأخلص وجهه لفاطر الكون. فالتوحيدُ توجيهُ القلبِ كلِّه للخالق وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توجيهُ القلبِ والعبادةِ لفاطرِ السماوات وحده."},"action":{"text":"وجّه قلبك وعبادتك لله فاطرِ الكون وحده، حنيفًا مخلصًا لا تشرك به شيئًا."}}]},{"title":"حجّةُ إبراهيم على قومه، والأمنُ لأهل التوحيد","range":[80,83],"theme":"ثباتُ الموحّدِ وعدمُ خوفه من الشركاء، وأنّ الأمنَ لمن لم يخلط إيمانه بشرك","verses":[{"n":80,"reflection":{"text":"«وحاجه قومه قال أتحاجوني في الله وقد هدان ولا أخاف ما تشركون به إلا أن يشاء ربي شيئا وسع ربي كل شيء علما أفلا تتذكرون»: جادله قومُه في التوحيد، فقال: أتجادلونني في الله وقد هداني إليه؟ ولا أخاف آلهتكم فإنّها لا تضرّ إلا أن يشاء الله؛ وسع علمُ ربّي كلَّ شيء؛ أفلا تتذكّرون فتعتبروا؟ فالموحّدُ لا يخاف إلا الله. فمن هداه الله لا تزلزله شبهات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على التوحيدِ وعدمُ الخوفِ من غير الله."},"action":{"text":"اثبت على توحيدك ولا تخف من معبوداتٍ لا تملك ضرًّا ولا نفعًا."}},{"n":81,"reflection":{"text":"«وكيف أخاف ما أشركتم ولا تخافون أنكم أشركتم بالله ما لم ينزل به عليكم سلطانا فأي الفريقين أحق بالأمن إن كنتم تعلمون»: كيف أخاف أصنامكم العاجزة وأنتم لا تخافون إشراككم بالله ما لا حجّةَ لكم عليه؟ فأيُّ الفريقين أحقُّ بالأمن: الموحّدُ أم المشرك؟ إن كنتم تعقلون فالموحّدُ أحقّ. فالأمنُ الحقيقيّ لأهل التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ أهلَ التوحيدِ أحقُّ بالأمن."},"action":{"text":"اطلب الأمنَ في التوحيد، فالموحّدُ آمنٌ والمشركُ خائفٌ وإن لم يشعر."}},{"n":82,"reflection":{"text":"«الذين آمنوا ولم يلبسوا إيمانهم بظلم أولئك لهم الأمن وهم مهتدون»: الذين آمنوا ولم يخلطوا إيمانهم بشرك (والظلمُ هنا الشرك، كما فسّره النبيُّ ﷺ بآية لقمان «إنّ الشرك لظلم عظيم») لهم الأمنُ التامّ من العذاب وهم المهتدون؛ فطمأنت الآيةُ الصحابةَ حين خافوا أن يكون كلُّ ظلمٍ مرادًا. فالأمنُ الكاملُ لمن سلم توحيده من الشرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الأمنِ بسلامةِ التوحيدِ من الشرك."},"action":{"text":"نقِّ توحيدك من الشرك دقيقِه وجليله، فبه يكون لك الأمنُ والهداية."}},{"n":83,"reflection":{"text":"«وتلك حجتنا آتيناها إبراهيم على قومه نرفع درجات من نشاء إن ربك حكيم عليم»: تلك الحجّةُ البالغةُ التي احتجّ بها إبراهيمُ على قومه من عندنا وفّقناه لها؛ ونرفع في العلم والإيمان درجاتِ من نشاء من عبادنا؛ إنّ ربّك حكيمٌ يضع الأشياء مواضعها، عليمٌ بمن يستحقّ الرفعة. فالحجّةُ توفيقٌ، والرفعةُ بعلمٍ وحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكيم","العليم"],"heart_state":{"text":"طلبُ رفعةِ الدرجاتِ بالعلمِ والحجّةِ من الله."},"action":{"text":"اطلب من الله أن يرفع درجتك بالعلم والحجّة، فالتوفيقُ منه وحده."}}]},{"title":"سلسلةُ الأنبياء المهديّين، والاقتداءُ بهم","range":[84,90],"theme":"تعدادُ الأنبياء الذين هداهم الله، وأنّ الشركَ يُحبط العمل، والأمرُ بالاقتداء بهداهم","verses":[{"n":84,"reflection":{"text":"«ووهبنا له إسحاق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمان وأيوب ويوسف وموسى وهارون وكذلك نجزي المحسنين»، وهبنا لإبراهيم إسحاقَ ويعقوبَ وهديناهما، وهدينا نوحًا قبله، ومن ذرّيّته داودَ وسليمانَ وأيّوبَ ويوسفَ وموسى وهارون؛ وكذلك نجزي المحسنين بالهداية والذرّيّة الصالحة. فجزاءُ الإحسان الهدايةُ والذرّيّةُ المباركة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المحسنين"],"heart_state":{"text":"الإحسانُ سببُ الهدايةِ والذرّيّةِ الصالحة."},"action":{"text":"أحسِن في عملك ودعائك، فالله يجزي المحسنين بالهداية والذرّيّة الصالحة."}},{"n":85,"reflection":{"text":"«وزكريا ويحيى وعيسى وإلياس كل من الصالحين»، وهدينا زكريّا ويحيى وعيسى وإلياس؛ كلُّهم من الصالحين الكاملين في الصلاح؛ فالصلاحُ جامعُ صفاتهم. فالصلاحُ غايةٌ يشترك فيها كلُّ الأنبياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالصالحين من أنبياء الله."},"action":{"text":"اجعل الصلاحَ غايتك، مقتديًا بأنبياء الله الصالحين في إيمانهم وعملهم."}},{"n":86,"reflection":{"text":"«وإسماعيل واليسع ويونس ولوطا وكلا فضلنا على العالمين»، وهدينا إسماعيلَ واليسعَ ويونسَ ولوطًا؛ وكلَّ هؤلاء الأنبياء فضّلناهم على عالمي زمانهم بالنبوّة والرسالة. فالنبوّةُ أعظمُ تفضيلٍ وشرف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ منزلةِ الأنبياء الذين فضّلهم الله."},"action":{"text":"عظّم أنبياءَ الله الذين اصطفاهم وفضّلهم، واتّبع سبيلهم."}},{"n":87,"reflection":{"text":"«ومن آبائهم وذرياتهم وإخوانهم واجتبيناهم وهديناهم إلى صراط مستقيم»، وهدينا من آبائهم وذرّيّاتهم وإخوانهم من صلح، واصطفيناهم لرسالتنا، ووفّقناهم إلى الطريق المستقيم؛ فالهدايةُ اصطفاءٌ من الله. فالهدايةُ نعمةٌ يمنّ الله بها على من اصطفى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الهدايةِ والاصطفاء."},"action":{"text":"اشكر الله إن هداك واصطفاك للحقّ، واسأله الثباتَ على صراطه المستقيم."}},{"n":88,"reflection":{"text":"«ذلك هدى الله يهدي به من يشاء من عباده ولو أشركوا لحبط عنهم ما كانوا يعملون»: ذلك الذي وُفّق إليه الأنبياء هو هدى الله يهدي به من يشاء من عباده؛ ولو أنّ هؤلاء الأنبياء، مع علوّ مقامهم، أشركوا لبطلت أعمالهم؛ فكيف بغيرهم؟ فالشركُ يُحبط أعظمَ الأعمال. فاحذر الشركَ فإنّه يُحبط العمل كلَّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشركِ الذي يُحبط العمل ولو عظُم."},"action":{"text":"احفظ توحيدك، فالشركُ يُحبط العملَ كلَّه ولو كان صاحبُه نبيًّا."}},{"n":89,"reflection":{"text":"«أولئك الذين آتيناهم الكتاب والحكم والنبوة فإن يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكافرين»: أولئك الأنبياءُ آتيناهم الكتبَ والفهمَ والنبوّة؛ فإن يكفر بهذه النعم قومُك يا محمد فقد هيّأنا لها قومًا (كالمهاجرين والأنصار ومن تبعهم) يؤمنون بها ولا يكفرون؛ فدينُ الله لا يضيع بكفر الكافرين. فالحقُّ محفوظٌ يحمله من يؤمن به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الحقَّ محفوظٌ يحمله المؤمنون."},"action":{"text":"اثبت على الحقّ، فإن أعرض عنه قومٌ حمله آخرون، ودينُ الله باقٍ لا يضيع."}},{"n":90,"reflection":{"text":"«أولئك الذين هدى الله فبهداهم اقتده قل لا أسألكم عليه أجرا إن هو إلا ذكرى للعالمين»: أولئك الأنبياءُ الذين هداهم الله، فاقتدِ يا محمد بهداهم في التوحيد والصبر ومكارم الأخلاق؛ وقل: لا أطلب على تبليغ القرآن أجرًا، ما هو إلا تذكرةٌ للعالمين كلِّهم. فالاقتداءُ بالأنبياء منهجٌ، والدعوةُ لله لا للأجر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بهدى الأنبياءِ والإخلاصُ في الدعوة."},"action":{"text":"اقتدِ بهدى الأنبياء في توحيدك وأخلاقك، وادعُ إلى الله لوجهه لا لأجر."}}]},{"title":"ما قدروا الله حقّ قدره، وبركةُ القرآن","range":[91,94],"theme":"جحودُ من أنكر الوحي، وبركةُ القرآن، وأظلمُ الناسِ مفترٍ، وهولُ الموتِ للظالمين","verses":[{"n":91,"reflection":{"text":"«وما قدروا الله حق قدره إذ قالوا ما أنزل الله على بشر من شيء قل من أنزل الكتاب الذي جاء به موسى نورا وهدى للناس تجعلونه قراطيس تبدونها وتخفون كثيرا... قل الله ثم ذرهم في خوضهم يلعبون»: ما عظّموا الله حقَّ عظمته إذ أنكروا إنزالَ الوحي على البشر؛ قل: من أنزل التوراةَ على موسى نورًا وهدًى، التي تكتبونها أوراقًا تُظهرون بعضها وتُخفون كثيرًا (كصفة النبيّ)؟ إنّه الله؛ ثمّ اتركهم في باطلهم يلعبون. فإنكارُ الوحي جهلٌ بقدر الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله حقَّ قدرِه بالإيمان بوحيه."},"action":{"text":"عظّم اللهَ حقَّ قدره، وآمن بأنّه أنزل الوحيَ رحمةً وهدًى للناس."}},{"n":92,"reflection":{"text":"«وهذا كتاب أنزلناه مبارك مصدق الذي بين يديه ولتنذر أم القرى ومن حولها والذين يؤمنون بالآخرة يؤمنون به وهم على صلاتهم يحافظون»، وهذا القرآنُ كتابٌ أنزلناه كثيرَ الخير والبركة، مصدّقًا للكتب قبله، لتنذر به مكّةَ (أمَّ القرى) ومن حولها من الناس أجمعين؛ والذين يؤمنون بالآخرة يؤمنون به لأنّهم يخافون الحساب، وهم يحافظون على صلواتهم؛ فعلامةُ الإيمان بالقرآن المحافظةُ على الصلاة. فبركةُ القرآن في هدايته والعملِ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ بركةِ القرآن والمحافظةُ على الصلاة."},"action":{"text":"اقرأ القرآنَ المبارك واعمل به، وحافظ على صلاتك، فذاك علامةُ الإيمان به."}},{"n":93,"reflection":{"text":"«ومن أظلم ممن افترى على الله كذبا أو قال أوحي إلي ولم يوح إليه شيء ومن قال سأنزل مثل ما أنزل الله ولو ترى إذ الظالمون في غمرات الموت والملائكة باسطو أيديهم أخرجوا أنفسكم اليوم تجزون عذاب الهون بما كنتم تقولون على الله غير الحق وكنتم عن آياته تستكبرون»: لا أظلمَ ممّن كذب على الله، أو ادّعى الوحيَ كذبًا، أو زعم أنّه يأتي بمثل القرآن؛ ولو ترى الظالمين في سكرات الموت والملائكةُ تبسط أيديها بالعذاب: أخرجوا أنفسكم! اليوم تُجزَون عذابَ الذلّ بما كنتم تقولون على الله الباطلَ وتستكبرون عن آياته؛ لرأيت هولًا عظيمًا. فالكذبُ على الله والاستكبارُ عن آياته أظلمُ الظلم وأشدُّه عاقبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الكذبِ على الله والاستكبارِ عن آياته."},"action":{"text":"لا تقُل على الله ما لم يقُل، ولا تستكبر عن آياته، فعاقبةُ ذلك عذابُ الهون."}},{"n":94,"reflection":{"text":"«ولقد جئتمونا فرادى كما خلقناكم أول مرة وتركتم ما خولناكم وراء ظهوركم وما نرى معكم شفعاءكم الذين زعمتم أنهم فيكم شركاء لقد تقطع بينكم وضل عنكم ما كنتم تزعمون»: يقال لهم يومَ القيامة: جئتمونا منفردين بلا مالٍ ولا أهلٍ ولا شفيع، كما خلقناكم أوّلَ مرّةٍ عراةً حفاةً، وتركتم ما أعطيناكم من المال خلف ظهوركم؛ ولا نرى معكم شفعاءكم الذين زعمتموهم شركاء؛ لقد انقطعت الوصلُ بينكم وغاب عنكم ما كنتم تزعمون. فيأتي العبدُ فردًا بلا ما اتّكل عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقاء الله فردًا بلا مالٍ ولا شفيعٍ سواه."},"action":{"text":"اعمل صالحًا تلقى الله به، فستأتيه فردًا، ويتخلّى عنك كلُّ ما سواه."}}]},{"title":"آياتُ الخلق: فالقُ الحبِّ والإصباح","range":[95,100],"theme":"دلائلُ التوحيد في الحبّ والنوى والصبح والليل والنجوم والنبات، وبطلانُ نسبةِ الشركاء والولد","verses":[{"n":95,"reflection":{"text":"«إن الله فالق الحب والنوى يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فأنى تؤفكون»: إنّ الله يشقّ الحبّةَ والنواةَ فيُخرج منها الزرعَ والنخل؛ ويُخرج الحيَّ من الميّت (كالنبات من الحبّة، والإنسان من النطفة)، والميّتَ من الحيّ (كالبيضة من الطير)؛ ذلكم الله الخالق، فكيف تُصرَفون عن عبادته إلى غيره؟ فمن يفعل هذا وحده هو المعبود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في إخراجِ الحيّ من الميّت دليلًا على التوحيد."},"action":{"text":"تأمّل في الحبّة تنشقّ عن زرع، فمن يُحيي بها الأرضَ هو الله وحده، فاعبده."}},{"n":96,"reflection":{"text":"«فالق الإصباح وجعل الليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم»: يشقّ ظلمةَ الليل بضياء الصبح، وجعل الليلَ راحةً وسكونًا للأبدان، والشمسَ والقمرَ يجريان بحسابٍ دقيقٍ تُعرف به الأوقات والسنون؛ ذلك تقديرُ العزيز الذي لا يُغالَب، العليمِ بمصالح خلقه. فنظامُ الكون آيةُ عزّةٍ وعلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العزيز","العليم"],"heart_state":{"text":"التفكّرُ في نظامِ الليلِ والنهارِ والفلك."},"action":{"text":"تأمّل انشقاقَ الصبح وسكونَ الليل ودقّةَ حساب الشمس والقمر، فذاك تقديرُ العزيز العليم."}},{"n":97,"reflection":{"text":"«وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر قد فصلنا الآيات لقوم يعلمون»: هو الذي جعل النجومَ زينةً ومنارًا تهتدون بها في ظلمات البرّ والبحر إلى مقاصدكم؛ قد بيّنّا الآياتِ لقومٍ يعلمون فينتفعون بها. فالنجومُ نعمةٌ للاهتداء بها في الأسفار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ النجومِ والاهتداءِ بها."},"action":{"text":"اشكر الله على نعمة النجوم التي تهتدي بها، وتأمّل في دلائل التوحيد فيها."}},{"n":98,"reflection":{"text":"«وهو الذي أنشأكم من نفس واحدة فمستقر ومستودع قد فصلنا الآيات لقوم يفقهون»: هو الذي خلقكم جميعًا من نفسٍ واحدة (آدم)؛ فلكم مستقرٌّ في الأرحام أو على ظهر الأرض، ومستودعٌ في الأصلاب أو القبور؛ قد بيّنّا الآياتِ لقومٍ يفقهون معانيها. فأصلُكم واحد، وأطواركم بيد الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في أصلِ الخلقِ وأطوارِه."},"action":{"text":"تأمّل أنّ أصلك من نفسٍ واحدة، وأنّ الله ينقلك في أطوارٍ من صلبٍ إلى رحمٍ إلى قبر."}},{"n":99,"reflection":{"text":"«وهو الذي أنزل من السماء ماء فأخرجنا به نبات كل شيء فأخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانية وجنات من أعناب والزيتون والرمان مشتبها وغير متشابه انظروا إلى ثمره إذا أثمر وينعه إن في ذلكم لآيات لقوم يؤمنون»: هو الذي أنزل المطرَ فأنبت به كلَّ أنواع النبات: الزرعَ ذا الحبّ المتراكب، والنخلَ ذا العناقيد الدانية، وجنّاتِ الأعناب والزيتونِ والرمّان، متشابهًا في الشكل مختلفًا في الطعم؛ انظروا إلى الثمر حين يظهر ثمّ ينضج؛ إنّ في ذلك لآياتٍ لقومٍ يؤمنون. فاختلافُ الثمار من ماءٍ واحدٍ آيةٌ على القدرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في النباتِ والثمرِ آيةً على القدرة."},"action":{"text":"تأمّل الثمرةَ كيف تنشأ وتنضج من ماءٍ واحدٍ وأرضٍ واحدة، فذاك آيةُ قدرةِ الله."}},{"n":100,"reflection":{"text":"«وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنات بغير علم سبحانه وتعالى عما يصفون»، ومع كلّ هذه الآيات جعل المشركون لله شركاء من الجنّ يعبدونهم، والله خلقهم؛ واختلقوا له بنين وبنات (كقولهم الملائكةُ بناتُ الله) بلا علمٍ ولا دليل؛ تنزّه الله وتعالى عمّا يصفونه به من النقص. فنسبةُ الشريك والولد افتراءٌ يتنزّه الله عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["سبحانه"],"heart_state":{"text":"تنزيهُ الله عن الشريكِ والولدِ وكلِّ نقص."},"action":{"text":"نزّه الله عن كلّ ما لا يليق به من شريكٍ أو ولد، فهو الخالقُ المنزّه."}}]},{"title":"بديعُ السماوات، ولا تدركه الأبصار","range":[101,103],"theme":"تنزيهُ الخالقِ عن الولد، وأنّه خالقُ كلِّ شيءٍ، لطيفٌ لا تدركه الأبصار","verses":[{"n":101,"reflection":{"text":"«بديع السماوات والأرض أنى يكون له ولد ولم تكن له صاحبة وخلق كل شيء وهو بكل شيء عليم»: مبدعُ السماوات والأرض على غير مثالٍ سبق؛ كيف يكون له ولدٌ ولا زوجةَ له، والولدُ يكون عن صاحبة؟ وهو خالقُ كلِّ شيء، فكيف يكون بعضُ خلقه ولدًا له؟ وهو بكلّ شيءٍ عليم. فنسبةُ الولد إليه محالٌ عقلًا وشرعًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["البديع","العليم"],"heart_state":{"text":"تنزيهُ الخالقِ عن الصاحبةِ والولد."},"action":{"text":"نزّه الله الخالقَ عن الولد والصاحبة، فهو خالقُ كلِّ شيءٍ لا يشبهه شيء."}},{"n":102,"reflection":{"text":"«ذلكم الله ربكم لا إله إلا هو خالق كل شيء فاعبدوه وهو على كل شيء وكيل»: ذلكم الموصوفُ بهذه الصفات هو الله ربّكم، لا معبودَ بحقٍّ سواه، خالقُ كلِّ شيء؛ فأخلصوا له العبادة؛ وهو القائمُ على كلّ شيءٍ بالحفظ والتدبير. فمن كان خالقًا مدبّرًا هو المستحقُّ للعبادة والتوكّل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الوكيل"],"heart_state":{"text":"إفرادُ الخالقِ المدبّرِ بالعبادةِ والتوكّل."},"action":{"text":"اعبد اللهَ وحده خالقَ كلّ شيء، وتوكّل عليه، فهو الوكيلُ القائمُ بأمرك."}},{"n":103,"reflection":{"text":"«لا تدركه الأبصار وهو يدرك الأبصار وهو اللطيف الخبير»: لا تحيط به الأبصارُ إحاطةً في الدنيا (ويراه المؤمنون في الآخرة كما تواتر)، وهو يدرك الأبصارَ ويحيط بها؛ وهو اللطيفُ بعباده يوصل إليهم مصالحهم بلطفه، الخبيرُ بدقائق الأمور؛ فعظمتُه فوق الإدراك، ولطفُه وخبرتُه تحيط بك. فتنزيهٌ عن الإحاطة، وإثباتُ لطفه وخبرته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["اللطيف","الخبير"],"heart_state":{"text":"تعظيمُ الله اللطيفِ الخبيرِ الذي لا تحيط به الأبصار."},"action":{"text":"عظّم اللهَ الذي لا تدركه الأبصار وهو يراك، واطمئن إلى لطفه وخبرته بك."}}]},{"title":"البصائرُ والوحي، والنهيُ عن سبِّ آلهةِ المشركين","range":[104,110],"theme":"القرآنُ بصائرُ لمن أبصر، واتّباعُ الوحي، وحفظُ حرمةِ التوحيدِ حتى في الجدال","verses":[{"n":104,"reflection":{"text":"«قد جاءكم بصائر من ربكم فمن أبصر فلنفسه ومن عمي فعليها وما أنا عليكم بحفيظ»: قد جاءكم من ربّكم حججٌ وبيّناتٌ تُبصر بها القلوبُ الحقَّ؛ فمن أبصر بها فنفعُه لنفسه، ومن عمي عنها فضررُه على نفسه؛ ولستُ حفيظًا أحاسبكم، إنّما أنا مبلّغ. فالانتفاعُ بالبصائر أو الحرمانُ منها يعود على صاحبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإبصارُ بالقرآنِ والانتفاعُ به لنفسك."},"action":{"text":"افتح قلبك لبصائر القرآن، فمن أبصر بها فلنفسه، ومن أعرض فعلى نفسه."}},{"n":105,"reflection":{"text":"«وكذلك نصرف الآيات وليقولوا درست ولنبينه لقوم يعلمون»، وكما بيّنّا الآياتِ نصرّفها بأنواع البيان؛ فيقول المعاندون: تعلّمتَها من غيرك؛ لكنّ الحكمةَ أن نبيّن الحقَّ لقومٍ يعلمون فينتفعون؛ فالبيانُ يهدي الطالبَ ويقيم الحجّةَ على المعاند. فالآياتُ تُصرّف رحمةً بالمهتدي وحجّةً على المعاند.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانتفاعُ بتصريفِ الآياتِ لا معارضتُها."},"action":{"text":"تدبّر تنوّعَ بيان القرآن لتنتفع، ولا تكن كمن يعارضه بالتّهم."}},{"n":106,"reflection":{"text":"«اتبع ما أوحي إليك من ربك لا إله إلا هو وأعرض عن المشركين»: اتّبع يا محمد ما أوحاه الله إليك والزمه، فلا معبودَ بحقٍّ سواه؛ وأعرض عن المشركين ولا يشغلك عنادُهم؛ فمهمّتُك الاتّباعُ والبلاغ. فسبيلُ النجاة اتّباعُ الوحي والإعراضُ عن أهل الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الوحي والإعراضُ عن أهل الباطل."},"action":{"text":"اتّبع الوحيَ والزمه، وأعرض عمّن يعاند الحقّ، فمهمّتُك البلاغ لا الجدال العقيم."}},{"n":107,"reflection":{"text":"«ولو شاء الله ما أشركوا وما جعلناك عليهم حفيظا وما أنت عليهم بوكيل»: لو شاء الله لمنعهم من الشرك قهرًا، لكنّه ابتلاءٌ بحكمته؛ ولستَ يا محمد حفيظًا تحصي أعمالهم ولا موكّلًا بهدايتهم؛ إنّما أنت مبلّغ؛ فلا تحمل ما ليس عليك. فالهدايةُ بيد الله، والداعي مبلّغٌ لا محاسب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ بأنّ الهدايةَ بيد الله وطرحُ ما لا يُطاق."},"action":{"text":"بلّغ ولا تحمل همّ هداية الناس فوق طاقتك، فمشيئةُ الهداية لله."}},{"n":108,"reflection":{"text":"«ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل أمة عملهم ثم إلى ربهم مرجعهم فينبئهم بما كانوا يعملون»: لا تسبّوا آلهةَ المشركين فيسبّوا اللهَ ظلمًا وجهلًا مقابلةً لكم؛ فسدّ الله ذريعةَ الشرّ ولو كان في السبّ مصلحةٌ ظاهرة؛ ثمّ مرجعُ الجميع إليه فيجازيهم. قاعدةٌ عظيمة في سدّ الذرائع: يُترك الجائزُ إذا أفضى إلى محرّمٍ أعظم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سدُّ الذرائعِ وتركُ ما يُفضي إلى شرٍّ أكبر."},"action":{"text":"لا تفعل مباحًا يجرّ إلى منكرٍ أعظم، فحفظُ حرمة الله أولى من التشفّي."},"qadiyya":{"title":"قضيّةُ مباحٍ مُنع لِما يُفضي إليه","question":"قال الله: ﴿ولا تسبّوا الذين يدعون من دون الله فيسبّوا الله عدوًا بغير علم﴾.\nوالنهيُ ها هنا عن فعلٍ **ليس بقبيحٍ في نفسه**؛ فإنّ إهانة الوثن إهانةٌ للباطل.\nثمّ إنّ العلّة المذكورة فعلٌ **يصدر من غير المنهيّ**؛ فالمخاطَبُ مسلم، والسبُّ المحذور يقع من المشرك.\nفالقضيّة: كيف يُمنع المسلمُ من أمرٍ أصلُه قربة؟ ثمّ: ما وجهُ اتّصال ﴿كذلك زيّنّا لكلّ أمّة عملهم﴾ بالنهي قبله؟ ثمّ: ما القاعدةُ التي تخرج من الآية، وبأيّ قيدٍ تخرج؟","background":"ولا يستقيم النظرُ في الآية حتى يُفرَّق بين اعتبارين في الفعل الواحد:\nاعتبارُه في ذاته، وهو النظرُ في صفة الفعل نفسِه.\nواعتبارُه بما يؤول إليه، وهو النظرُ فيما يتولّد عنه.\n**فالحكمُ قد يختلف باختلاف الاعتبارين والفعلُ واحد.**\nوثمّ تفريقٌ ثانٍ يحتاجه القارئ: أنّ السبّ إهانةٌ وشتم، وليس هو بيانَ بطلان المعبود؛ **والكلامُ في الآية على الأوّل**.","what_happened":"**افتتح السعديُّ بتقرير أنّ المنهيّ عنه مأذونٌ فيه في الأصل**: «ينهى الله المؤمنين عن أمر كان جائزا، بل مشروعا في الأصل، وهو سب آلهة المشركين، التي اتخذت أوثانا وآلهة مع الله، التي يتقرب إلى الله بإهانتها وسبها».\n⭐ ثمّ ذكر العلّة، وهي المآل: «ولكن لما كان هذا السب طريقا إلى سب المشركين لرب العالمين، الذي يجب تنزيه جنابه العظيم عن كل عيب، وآفة، وسب، وقدح».\nثمّ صرّح بالنهي معلّلًا بحال المشركين: «نهى الله عن سب آلهة المشركين، لأنهم يحمون لدينهم، ويتعصبون له».\nثمّ علّل هذه الحماية بما في الآية من التزيين: «لأن كل أمة، زين الله لهم عملهم، فرأوه حسنا، وذبوا عنه، ودافعوا بكل طريق، حتى إنهم، ليسبون الله رب العالمين، الذي رسخت عظمته في قلوب الأبرار والفجار، إذا سب المسلمون آلهتهم».\nثمّ فسّر آخر الآية: «ولكن الخلق كلهم، مرجعهم ومآلهم، إلى الله يوم القيامة، يعرضون عليه، وتعرض أعمالهم، فينبئهم بما كانوا يعملون، من خير وشر».\n⭐ **ثمّ ختم باستخراج القاعدة**: «وفي هذه الآية الكريمة، دليل للقاعدة الشرعية وهو أن الوسائل تعتبر بالأمور التي توصل إليها، وأن وسائل المحرم، ولو كانت جائزة تكون محرمة، إذا كانت تفضي إلى الشر».","the_verdict":"**فالحاصلُ أنّ الحكم تغيّر بالمآل لا بالفعل.**\nفقد اجتمع في كلام الإمام للفعل الواحد وصفان: أنّه «مشروعا في الأصل»، وأنّه منهيٌّ عنه. **ولا تناقض؛ فالأوّلُ باعتبار ذاته، والثاني باعتبار ما يوصل إليه.**\nوأمّا كيف يُمنع المسلمُ من أمرٍ أصلُه قربة، فجوابُه في لفظه: أنّ السبّ صار «طريقا» إلى سبّ الله. فلم يُنظر إلى ما في الفعل من إهانة الباطل، بل إلى ما يتولّد عنه من القدح في جناب من «يجب تنزيه جنابه العظيم». **والذي يفوت بالترك أصغرُ من الذي يقع بالفعل**؛ فإهانةُ وثنٍ لا تعدل قدحًا في الله.\n⭐ وأمّا وجهُ ﴿كذلك زيّنّا لكلّ أمّة عملهم﴾ فقد جعله الإمامُ علّةً لحمايتهم وتعصّبهم. وفائدةُ ذلك عندي: **أنّ الإفضاء ها هنا ليس ظنًّا في قومٍ بأعيانهم، بل مبنيٌّ على أمرٍ مطّرد في الأمم.**\nوفي الآية بعدُ أنّ الفعل المتولّد موصوفٌ بأنّه ﴿عدوًا بغير علم﴾، أي أنّه مذمومٌ في نفسه؛ **ومع ذلك توجّه النهيُ إلى من يفتح الباب لا إلى من يقع منه الإثم**.\n⭐ وأمّا القاعدةُ فقد صرّح بها وقيّدها بقيدين: قيّد الوسيلةَ بأنّها من «وسائل المحرم»، وعلّق تحريمها بقوله «إذا كانت تفضي إلى الشر». **فالقيدان ركنٌ فيها لا زيادةٌ عليها.** فالمعتبَرُ محرّمٌ يُوصَل إليه، لا مجرّدُ ما يُكره. وقد وقع ذلك في الآية على سبّ الله، وهو مثالُ القاعدة لا حدُّها.\nوموضعُ الغلط عند من لم ينتبه جهتان:\nالأولى: من يقف عند أصل الفعل، فيقول هذا جائز، ثمّ يمضي ولا يسأل ماذا يُنتج.\nوالثانية: من يُسقط القيدين، **فيصير كلُّ ما يُغضب أحدًا ممنوعًا عنده**.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: قدّر الجواب قبل أن تتكلّم. فإذا هممتَ بكلمةٍ في باطلٍ أمام أهله، فانظر ماذا يقولون بعدها. **فإن كان مآلُها أن يُقدح في الدين فأمسك**، وأنت لم تترك حقًّا، بل تركتَ طريقًا.\nوالثاني: لا تكتفِ بسؤال الجواز. **اجعل لكلّ ما تُقدم عليه سؤالين: أمأذونٌ فيه؟ وإلامَ يُفضي؟** ولا تُمضِ حتى يستقيم الجوابان.\nوالثالث: إذا منعتَ من مباحٍ فاذكر المحرّم الذي يُفضي إليه. **فالقاعدةُ في وسائل المحرّم، لا في وسائل ما تكرهه أنت.**","grade":"ma'thur","source":"تفسيرُ السعديّ لأصل الفعل («ينهى الله المؤمنين عن أمر كان جائزا»)، وتعليلُه بالمآل («ولكن لما كان هذا السب طريقا»)، وتصريحُه بالنهي («نهى الله عن سب آلهة المشركين»)، وتفسيرُه التزيين («لأن كل أمة، زين الله لهم عملهم»)، وتفسيرُه المرجع والإنباء («ولكن الخلق كلهم، مرجعهم ومآلهم»)، وتقريرُه القاعدة وقيديها («وفي هذه الآية الكريمة، دليل للقاعدة الشرعية»): كلُّها بنصّها في تفسير السعديّ (٦:١٠٨).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين اعتبار الفعل في ذاته واعتباره بمآله، تمهيدٌ منّا، وليس نصًّا للسعديّ، وإن كان مبنيًّا على تعليله بالطريق.\nوكذلك تفريقُنا بين السبّ وبيان بطلان المعبود، تفريقٌ منّا في معنى اللفظ، ولم يتعرّض له.\nوأمّا قولُنا إنّ الفائت بالترك أصغرُ من الواقع بالفعل، فموازنةٌ منّا؛ والإمامُ إنّما وصف عظمة ما يجب تنزيهه ولم يعقد هذه المقابلة بلفظه.\nوأمّا استدلالُنا بـ﴿عدوًا بغير علم﴾ على أنّ الفعل المتولّد مذمومٌ في نفسه وأنّ النهي مع ذلك توجّه إلى فاتح الباب، فاستنباطٌ منّا؛ ولم يتعرّض له في هذا الموضع.\nوأمّا قولُنا إنّ الإفضاء مبنيّ على أمرٍ مطّرد لا على ظنّ، فوجهٌ استخرجناه من تعليله بالتزيين، ولم ينصّ عليه بهذا اللفظ.\nوأمّا نصُّ القاعدة وقيداها فله بلفظه. وأمّا قولُنا إنّ سبّ الله مثالُها لا حدُّها، وإنّ على المانع أن يذكر المحرّم الذي يُفضي إليه، فضبطٌ منّا استخرجناه من قوله «وسائل المحرم»، ولم ينصّ عليه؛ ولم يتعرّض الإمامُ لمرتبة الإفضاء.\nوأمّا تقسيمُنا موضع الغلط جهتين، وترتيبُنا الأسئلة، والثلاثةُ التي في آخر الباب، فمن عندنا. وليس في المصدر ها هنا إلّا الأصل.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":109,"reflection":{"text":"«وأقسموا بالله جهد أيمانهم لئن جاءتهم آية ليؤمنن بها قل إنما الآيات عند الله وما يشعركم أنها إذا جاءت لا يؤمنون»: حلف المشركون مؤكّدين أنّهم لو جاءتهم آيةٌ حسّيّةٌ يقترحونها لآمنوا؛ قل: الآياتُ عند الله ينزّلها بحكمته لا باقتراحكم؛ وما يدريكم أنّها لو جاءت لا يؤمنون؟ فقد عاندوا آياتٍ كثيرة. فالمعاندُ لا تنفعه الآياتُ المقترحة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ العنادَ لا تشفيه الآياتُ المقترحة."},"action":{"text":"لا تعلّق إيمانك على آيةٍ تقترحها، فالمعاندُ لا يؤمن ولو رأى كلَّ آية."}},{"n":110,"reflection":{"text":"«ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة ونذرهم في طغيانهم يعمهون»، ونصرف قلوبهم وأبصارهم عن الحقّ عقوبةً لهم كما أعرضوا عنه أوّلَ مرّةٍ باختيارهم؛ ونتركهم في ضلالهم يتحيّرون؛ فمن أعرض عن الهدى أوّلًا حُرمه جزاءً. فالإعراضُ الأوّلُ يجرّ عقوبةَ الحرمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ الأوّلِ الذي يجرّ الحرمان."},"action":{"text":"بادر بقبول الحقّ أوّلَ ما يتبيّن لك، فالإعراضُ عنه عقوبتُه تقليبُ القلب وحرمانُه."}}]},{"title":"عداوةُ الشياطين، وتمامُ كلمةِ الله","range":[111,117],"theme":"عنادُ المكذّبين، وعداوةُ شياطينِ الإنسِ والجنّ، وأنّ كلمةَ الله تامّةٌ صدقًا وعدلًا","verses":[{"n":111,"reflection":{"text":"«ولو أننا نزلنا إليهم الملائكة وكلمهم الموتى وحشرنا عليهم كل شيء قبلا ما كانوا ليؤمنوا إلا أن يشاء الله ولكن أكثرهم يجهلون»: لو أنّنا أجبنا اقتراحهم فأنزلنا الملائكةَ، وأحيينا لهم الموتى فكلّموهم، وجمعنا كلَّ آيةٍ أمامهم عِيانًا، ما آمنوا إلا أن يشاء الله هدايتهم؛ لكنّ أكثرهم يجهلون أنّ الهدايةَ بيد الله لا بالآيات. فالإيمانُ توفيقٌ لا مجرّدُ معاينة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الإيمانَ توفيقٌ من الله لا مجرّدُ رؤية."},"action":{"text":"اسأل الله الهدايةَ، فالإيمانُ بمشيئته لا يحصل بمجرّد كثرة الآيات."}},{"n":112,"reflection":{"text":"«وكذلك جعلنا لكل نبي عدوا شياطين الإنس والجن يوحي بعضهم إلى بعض زخرف القول غرورا ولو شاء ربك ما فعلوه فذرهم وما يفترون»، وكما جُعل لك أعداء، جعلنا لكلّ نبيٍّ أعداءً من مَرَدة الإنس والجنّ، يوسوس بعضُهم لبعضٍ بكلامٍ مزيّنٍ ظاهرُه حسنٌ وباطنُه خداعٌ وغرور؛ ولو شاء الله لمنعهم، لكنّه ابتلاء؛ فاتركهم وافتراءهم واصبر. فالعداوةُ للحقّ سنّةٌ، والصبرُ عليها طريقُ الأنبياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على عداوةِ أهل الباطلِ اقتداءً بالأنبياء."},"action":{"text":"اصبر على معاداة أهل الباطل، فهي سنّةٌ في كلّ نبيّ، واحذر زخرفَ قولهم."}},{"n":113,"reflection":{"text":"«ولتصغى إليه أفئدة الذين لا يؤمنون بالآخرة وليرضوه وليقترفوا ما هم مقترفون»، وليميل إلى زخرف القول قلوبُ الذين لا يؤمنون بالآخرة فيرضَوه ويعملوا ما يعملون من الآثام؛ فباطلُهم يجد قبولًا عند من فسدت فطرته؛ فمن لم يخف الآخرةَ مال إلى الباطل. فضعفُ الإيمان بالآخرة يجرّ إلى قبول الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقويةُ الإيمانِ بالآخرةِ ليُردّ الباطل."},"action":{"text":"قوِّ إيمانك بالآخرة، فمن ضعُف يقينه بها مال قلبُه إلى زخرف الباطل."}},{"n":114,"reflection":{"text":"«أفغير الله أبتغي حكما وهو الذي أنزل إليكم الكتاب مفصلا والذين آتيناهم الكتاب يعلمون أنه منزل من ربك بالحق فلا تكونن من الممترين»: قل: أأطلب حكمًا غيرَ الله يفصل بيننا، وهو الذي أنزل القرآنَ مبيّنًا للحلال والحرام؟ وعلماءُ أهل الكتاب يعلمون أنّه منزّلٌ من ربّك بالحقّ؛ فلا تكن من الشاكّين. فلا حَكَمَ فوق الله، ولا كتابَ فوق القرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحكيمُ كتابِ الله واليقينُ بأنّه الحقّ."},"action":{"text":"احتكم إلى كتاب الله وحده، وأيقن أنّه الحقُّ المنزّل، ولا تشكّ فيه."}},{"n":115,"reflection":{"text":"«وتمت كلمت ربك صدقا وعدلا لا مبدل لكلماته وهو السميع العليم»، وكملت كلماتُ ربّك (القرآن وشرعُه) صدقًا في أخبارها وعدلًا في أحكامها، فلا كذبَ في خبرها ولا جورَ في حكمها؛ لا أحدَ يقدر أن يبدّلها؛ وهو السميعُ لأقوال عباده، العليمُ بأحوالهم. فكلامُ الله كاملٌ لا يُنقَض ولا يُبدَّل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"الثقةُ بكمالِ كلامِ الله صدقًا وعدلًا."},"action":{"text":"اطمئن إلى أنّ خبرَ القرآن صدقٌ وحكمَه عدل، فلا مبدّلَ لكلمات الله."}},{"n":116,"reflection":{"text":"«وإن تطع أكثر من في الأرض يضلوك عن سبيل الله إن يتبعون إلا الظن وإن هم إلا يخرصون»، وإن تطع أكثرَ أهل الأرض يصرفوك عن دين الله، فإنّهم لا يتّبعون إلا الظنَّ والتخمين لا اليقين، وإنّما يكذبون ويحدسون؛ فالكثرةُ ليست دليلَ الحقّ. فلا تُقاس الحقيقةُ بالكثرة بل بالدليل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترار بالكثرةِ في تحرّي الحقّ."},"action":{"text":"لا تجعل كثرةَ الناس ميزانَ الحقّ، فأكثرهم على الظنّ، والحقُّ بالدليل."}},{"n":117,"reflection":{"text":"«إن ربك هو أعلم من يضل عن سبيله وهو أعلم بالمهتدين»: إنّ ربّك هو أعلمُ بمن ضلّ عن طريقه ومن اهتدى إليه؛ فهو يعلم أهلَ الحقّ من أهل الباطل، فكِل الأمرَ إليه؛ فلا تحزن على ضلال الضالّين. فعلمُ الله بالفريقين تامّ، فسلّم له الأمر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ علمِ حالِ الخلقِ إلى الله."},"action":{"text":"لا تحزن على من ضلّ، فالله أعلمُ بالضالّ والمهتدي، وسيجازي كلًّا بعمله."}}]},{"title":"التسميةُ على الذبائح، وتركُ الإثم","range":[118,121],"theme":"الأكلُ ممّا ذُكر اسمُ الله عليه، وتركُ ظاهرِ الإثم وباطنه، والحذرُ من طاعةِ الشيطان","verses":[{"n":118,"reflection":{"text":"«فكلوا مما ذكر اسم الله عليه إن كنتم بآياته مؤمنين»: كلوا مما ذُبح وذُكر اسمُ الله عليه، ولا تلتفتوا إلى تحريم المشركين وتحليلهم بأهوائهم، إن كنتم مؤمنين بآيات الله؛ فالإيمانُ يقتضي اتّباعَ شرعه في الحلّ والحرمة. فالتسميةُ على الذبيحة من تمام الإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقيّدُ بشرعِ الله في الطعامِ والتسميةِ عليه."},"action":{"text":"سمِّ الله على ذبحك وطعامك، والتزم حلالَ الله وحرامه اتّباعًا لإيمانك."}},{"n":119,"reflection":{"text":"«وما لكم ألا تأكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم إلا ما اضطررتم إليه وإن كثيرا ليضلون بأهوائهم بغير علم إن ربك هو أعلم بالمعتدين»: أيُّ مانعٍ يمنعكم من أكل ما ذُكر اسمُ الله عليه وقد بيّن لكم المحرّمات تفصيلًا، إلا حالَ الاضطرار فيباح؟ وإنّ كثيرًا من الناس يُضلّون غيرهم بأهوائهم بلا علم (كتحليل المشركين وتحريمهم)؛ وربّك أعلمُ بالمعتدين المتجاوزين لحدوده. فالتحليلُ والتحريمُ بالعلمِ لا بالهوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ الحلالِ والحرامِ إلى شرع الله لا الأهواء."},"action":{"text":"لا تحرّم حلالًا ولا تحلّل حرامًا بهواك، والزم ما فصّله الله لك."}},{"n":120,"reflection":{"text":"«وذروا ظاهر الإثم وباطنه إن الذين يكسبون الإثم سيجزون بما كانوا يقترفون»: اتركوا المعاصيَ الظاهرةَ (بالجوارح) والباطنةَ (بالقلب كالحسد والكبر)؛ فإنّ الذين يكتسبون الآثامَ سيُجازَون بما اقترفوا؛ فالإثمُ سرُّه وعلنُه سواءٌ في العقوبة. فطهّر ظاهرك وباطنك من الإثم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الإثمِ ظاهرِه وباطنِه معًا."},"action":{"text":"طهّر جوارحك وقلبك من المعاصي، فباطنُ الإثم كظاهره في الجزاء."}},{"n":121,"reflection":{"text":"«ولا تأكلوا مما لم يذكر اسم الله عليه وإنه لفسق وإن الشياطين ليوحون إلى أوليائهم ليجادلوكم وإن أطعتموهم إنكم لمشركون»: لا تأكلوا ما لم يُذكر اسمُ الله عليه (كذبائح المشركين للأصنام، أو الميتة)، فأكلُه خروجٌ عن الطاعة؛ وإنّ الشياطين يوسوسون لأوليائهم بشبهاتٍ ليجادلوكم في إباحة الميتة؛ فإن أطعتموهم في تحليل ما حرّم الله كنتم مشركين، لأنّكم جعلتموهم مشرّعين مع الله. فطاعةُ المخلوقِ في تحليل الحرام شركٌ في التشريع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي طاعةِ المخلوقِ في مخالفةِ شرعِ الله."},"action":{"text":"لا تُطع أحدًا في تحليل ما حرّم الله أو تحريم ما أحلّ، فتلك طاعةٌ في الشرك."}}]},{"title":"الميّتُ يُحيا بالنور، وشرحُ الصدرِ للإسلام","range":[122,127],"theme":"فرقٌ بين حيِّ القلبِ بالنورِ وميّتِه في الظلمات، وأنّ الهدايةَ شرحُ صدرٍ من الله","verses":[{"n":122,"reflection":{"text":"«أومن كان ميتا فأحييناه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمات ليس بخارج منها كذلك زين للكافرين ما كانوا يعملون»: أيستوي من كان ميّتَ القلب بالكفر فأحييناه بالإيمان وجعلنا له نورَ الهدى يمشي به في الناس بصيرةً، ومن هو في ظلمات الكفر لا يخرج منها؟ لا يستويان؛ وكذلك زُيّن للكافرين قبيحُ أعمالهم فرأوها حسنة. فالإيمانُ حياةٌ ونور، والكفرُ موتٌ وظلمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ حياةِ القلبِ بالإيمانِ ونورِ الهدى."},"action":{"text":"اطلب حياةَ قلبك بالإيمان ونورَ الهدى، فشتّان بين حيٍّ مستنيرٍ وميّتٍ في الظلمات."}},{"n":123,"reflection":{"text":"«وكذلك جعلنا في كل قرية أكابر مجرميها ليمكروا فيها وما يمكرون إلا بأنفسهم وما يشعرون»، وكما جعلنا في مكّة كبراءَ يصدّون عن الحقّ، جعلنا في كلّ قريةٍ كبارَ مجرميها يمكرون بالدعوة ويصدّون؛ وما يعود وبالُ مكرهم إلا عليهم وهم لا يشعرون. فمكرُ المجرمين يرتدّ عليهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ مكرَ أهلِ الباطلِ يعود عليهم."},"action":{"text":"لا يهُلْك مكرُ المتكبّرين على الحقّ، فمكرُهم السيّئُ يحيق بهم."}},{"n":124,"reflection":{"text":"«وإذا جاءتهم آية قالوا لن نؤمن حتى نؤتى مثل ما أوتي رسل الله الله أعلم حيث يجعل رسالته سيصيب الذين أجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون»: إذا جاءتهم آيةٌ قالوا حسدًا: لن نؤمن حتى نُعطى النبوّةَ مثلَ ما أُعطي الرسل؛ فردّ الله: الله أعلمُ بمن يستحقّ الرسالة فيضعها فيه، فليست بالتمنّي؛ وسيصيب المجرمين ذلٌّ عند الله وعذابٌ شديدٌ بمكرهم. فالاصطفاءُ للرسالة بعلم الله لا بأهواء الناس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لاصطفاءِ الله وتركُ الحسدِ لفضله."},"action":{"text":"سلّم لاختيار الله لأنبيائه وأوليائه، ولا تحسد فضلَ الله على من يشاء."}},{"n":125,"reflection":{"text":"«فمن يرد الله أن يهديه يشرح صدره للإسلام ومن يرد أن يضله يجعل صدره ضيقا حرجا كأنما يصعد في السماء كذلك يجعل الله الرجس على الذين لا يؤمنون»: فمن أراد الله هدايته وسّع صدره لقبول الإسلام فانشرح له وأقبل؛ ومن أراد إضلاله بعدله جعل صدره ضيّقًا حرجًا عن الإيمان كأنّما يُكلَّف صعودَ السماء عجزًا؛ وكذلك يجعل الله العذابَ والخذلانَ على من لا يؤمن. فشرحُ الصدر للإسلام علامةُ الهداية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سؤالُ الله شرحَ الصدرِ للإسلامِ والهداية."},"action":{"text":"اسأل الله أن يشرح صدرك للإسلام، فانشراحُ الصدر للحقّ علامةُ توفيقه."}},{"n":126,"reflection":{"text":"«وهذا صراط ربك مستقيما قد فصلنا الآيات لقوم يذكرون»، وهذا الذي شرعه الله وبيّنه هو صراطُ ربّك المستقيمُ الموصلُ إليه؛ قد بيّنّا الآياتِ وفصّلناها لقومٍ يتذكّرون فينتفعون؛ فالطريقُ واضحٌ لمن أراد. فصراطُ الله بيّنٌ لمن تذكّر واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ صراطِ الله المستقيمِ الواضح."},"action":{"text":"الزم صراطَ الله المستقيم الذي بيّنه، وتذكّر آياته لتنتفع بها وتثبت عليه."}},{"n":127,"reflection":{"text":"«لهم دار السلام عند ربهم وهو وليهم بما كانوا يعملون»: لأهل هذا الصراط دارُ السلامة من الآفات (الجنّة) عند ربّهم، وهو وليّهم الذي تولّاهم بتوفيقهم ونصرهم بسبب أعمالهم الصالحة؛ فالجنّةُ ثمرةُ الاستقامة، وولايةُ الله جزاءُ العمل. فأعظمُ ما ينال العبدُ ولايةَ الله ودارَ السلام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السلام","الولي"],"heart_state":{"text":"طلبُ ولايةِ الله ودارِ السلامِ بالعمل الصالح."},"action":{"text":"اعمل صالحًا لتنال ولايةَ الله ودارَ السلام، فهو وليُّ من عمل بطاعته."}}]},{"title":"حشرُ الجنِّ والإنس، وعدلُ الله في العقوبة","range":[128,132],"theme":"مساءلةُ من أضلّ وأُضلّ، وقيامُ الحجّةِ بالرسل، وأنّ لكلٍّ درجاتٍ بعمله","verses":[{"n":128,"reflection":{"text":"«ويوم يحشرهم جميعا يا معشر الجن قد استكثرتم من الإنس وقال أولياؤهم من الإنس ربنا استمتع بعضنا ببعض وبلغنا أجلنا الذي أجلت لنا قال النار مثواكم خالدين فيها إلا ما شاء الله إن ربك حكيم عليم»، ويومَ يجمع الله الثقلين يوبّخ شياطينَ الجنّ: قد أضللتم كثيرًا من الإنس؛ ويعترف أولياؤهم من الإنس أنّ بعضهم انتفع ببعضٍ (الجنُّ بالطاعة والإنسُ بقضاء الشهوات) حتى بلغوا آجالهم؛ فيقول الله: النارُ مثواكم خالدين فيها إلا ما شاء؛ إنّ ربّك حكيمٌ في حكمه، عليمٌ بمن يستحقّ. فالتعاونُ على الباطل يجمع أهلَه في النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الحكيم","العليم"],"heart_state":{"text":"الحذرُ من قرناءِ السوءِ من الإنسِ والجنّ."},"action":{"text":"احذر كلَّ قرينٍ يعينك على الباطل، فالتعاونُ على الشرّ يجمع أهلَه في النار."}},{"n":129,"reflection":{"text":"«وكذلك نولي بعض الظالمين بعضا بما كانوا يكسبون»، وكذلك نجعل بعضَ الظالمين أولياءَ لبعضٍ وأعوانًا، ونسلّط بعضَهم على بعضٍ جزاءً بما كسبوا من الظلم؛ فالظالمُ يُبتلى بظالمٍ مثله. فمن أسبابِ العقوبة أن يُسلَّط على الظالم من هو شرٌّ منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بأنّ الظلمَ يجلب تسلّطَ الظالمين."},"action":{"text":"اجتنب الظلم، فمن أسباب عقوبته أن يُسلَّط عليك ظالمٌ مثلك أو أشدّ."},"qadiyya":{"title":"قضيّةُ والٍ هو أثرٌ لا سبب","question":"قال الله: ﴿وكذلك نولّي بعض الظالمين بعضًا بما كانوا يكسبون﴾.\nوالآيةُ جاءت عقب ذكر الجنّ وأوليائهم من الإنس، ثمّ عمّمت الحكم بـ﴿وكذلك﴾.\nوموضعُ الإشكال أنّ التولية منسوبةٌ إلى الله، والمولَّى ظالم، والمولَّى عليه ظالم.\nفالقضيّة: كيف تُنسب التوليةُ إلى الله وهي عقوبة؟ ثمّ: كيف تكون عقوبةً والمعاقَبُ هو المسلَّطُ عليه؟ ثمّ: أين موقعُ الوالي من حال رعيّته، أسببٌ لها أم أثرٌ عنها؟","background":"وقبل الجواب أمران.\nالأوّل أنّ التولية في اللسان جعلُ الشيء وليًّا متصرّفًا؛ فتصدق على موالاة القرين لقرينه، وعلى ولاية الوالي على رعيّته. **فاللفظُ يسع الصورتين معًا**، وقد جاء في كلام الإمام ما يتناول القرين ثمّ ما يتناول السلطان.\nوالثاني أنّ الناس في ترتيب الفساد على مذهبين: **مذهبٌ يجعل الوالي أوّل السلسلة وحالَ الناس آخرها، ومذهبٌ يعكس الترتيب.** وقد ختمت الآيةُ بـ﴿بما كانوا يكسبون﴾، والكسبُ فعلُ العبد.","what_happened":"ابتدأ السعديُّ بردّ ﴿وكذلك﴾ إلى ما قبلها: «أي: وكما ولَّيْنَا الجن المردة وسلطناهم على إضلال أوليائهم من الإنس وعقدنا بينهم عقد الموالاة والموافقة، بسبب كسبهم وسعيهم بذلك».\n⭐ ثمّ رفع الحكم من الواقعة إلى السنّة: «كذلك من سنتنا أن نولي كل ظالم ظالما مثله، يؤزه إلى الشر ويحثه عليه، ويزهده في الخير وينفره عنه».\nثمّ حكم على هذه التولية نفسِها: «وذلك من عقوبات الله العظيمة الشنيع أثرها، البليغ خطرها».\nثمّ ردّ التبعة إلى صاحبها: «والذنب ذنب الظالم، فهو الذي أدخل الضرر على نفسه، وعلى نفسه جنى»، ثمّ أورد ﴿وما ربك بظلام للعبيد﴾.\n⭐ ثمّ قال: «ومن ذلك»، وساق صورةً في العمران: «أن العباد إذا كثر ظلمهم وفسادهم، ومنْعهم الحقوق الواجبة، ولَّى عليهم ظلمة، يسومونهم سوء العذاب، ويأخذون منهم بالظلم والجور أضعاف ما منعوا من حقوق الله، وحقوق عباده، على وجه غير مأجورين فيه ولا محتسبين».\nثمّ قابلها بالصورة الأخرى: «كما أن العباد إذا صلحوا واستقاموا، أصلح الله رعاتهم، وجعلهم أئمة عدل وإنصاف، لا ولاة ظلم واعتساف».","the_verdict":"فالحاصلُ أنّ الآية قانونٌ جارٍ لا خبرٌ عن واقعةٍ مضت؛ وقد ظهر ذلك في لفظه: «من سنتنا». والتوليةُ نفسُها عقوبةٌ عنده: «من عقوبات الله العظيمة».\n⭐ فإن قيل: كيف تُنسب إلى الله وهي عقوبةٌ بشرّ؟ فالجوابُ في كلامه: «والذنب ذنب الظالم، فهو الذي أدخل الضرر على نفسه»، ولذلك أعقبه بـ﴿وما ربك بظلام للعبيد﴾. وقد علّق العقدَ الأوّل بالكسب: «بسبب كسبهم وسعيهم بذلك»، وختمت الآيةُ بـ﴿بما كانوا يكسبون﴾؛ **فالتوليةُ لاحقةٌ للكسب لا سابقةٌ عليه**، والنسبةُ إلى الله نسبةُ جزاءٍ عادل.\n⭐ وأمّا كيف يكون المعاقَبُ هو المسلَّطَ عليه، فمدارُه على قيدٍ في كلامه لا يجوز إسقاطه: «إذا كثر ظلمهم وفسادهم». **فالمولَّى عليهم في هذه الصورة ظلمةٌ أيضًا**؛ مَنَعوا الحقوق الواجبة فأُخذت منهم قهرًا، وجاء الأخذ «أضعاف ما منعوا»؛ فالمقدارُ من جنس الممنوع مع زيادة، والصفةُ مقلوبة: منعٌ باختيار، وأخذٌ باضطرار.\nومن أسقط القيد غلط من وجهين: جعل كلَّ مبتلًى بوالٍ جائرٍ مستحقًّا لما نزل به، والإمامُ قيّد الصورة بكثرة الظلم؛ وجعل الآية عذرًا للمسلَّط، وقد وصفه بأنّه على وجهٍ لا أجر فيه ولا احتساب، فالآخذُ مأخوذٌ وإن كان سوطًا.\n⭐ وأمّا موقعُ الوالي فقد جاء في الطرفين في موضع الأثر: في الشرّ «ولَّى عليهم ظلمة»، وفي الخير «أصلح الله رعاتهم». **فالوالي في هذا الباب ثمرةٌ تُقطف لا بذرةٌ تُبذر.** وموضعُ الغلط أنّه يبدأ من آخر السلسلة، فيشتغل بتبديل الوالي وحالُه لم يتبدّل، فلا يُبدَّل له إلّا مثلُه.\nوفي كلامه ما هو أعمُّ من الولاية العامّة، فأوّلُ ما تناولته الظالمُ المولَّى الذي «يؤزه إلى الشر»، ثمّ جاءت ولاية الظلمة بـ«ومن ذلك». **فانظر في قرنائك قبل أن تنظر في سلطانك.**","for_you":"فأمّا الذي تخرج به فثلاثة.\nالأوّل: أدِّ حقًّا واجبًا تمنعه. اكتب اليوم ما عليك: أجرةُ عاملٍ أخّرتها، ودَينٌ حلّ أجله، وحقُّ قريبٍ قطعته. ثمّ أخرج واحدًا منها قبل أن ينقضي أسبوعُك؛ فمدارُ الصورة عند الإمام على منع «الحقوق الواجبة».\nوالثاني: انظر فيمن أنت والٍ عليه قبل أن تنظر في الوالي عليك. فأنت الوالي على أهلك، ومن تستأجره، ومن تُشرف على عمله. فاسأل واحدًا منهم اليوم عن مظلمةٍ عندك، ثمّ ارددها في مجلسك ذاك ولا تؤخّرها.\nوالثالث: زِن قرناءك بوصف الإمام. فقد وصف الظالم المولَّى بأنّه «يؤزه إلى الشر ويحثه عليه، ويزهده في الخير وينفره عنه». فاعرض مجالسك عليه، واترك في هذا الشهر مجلسًا واحدًا انطبق عليه، وضع مكانه مجلسًا يحثّك على الخير.","grade":"ma'thur","source":"تفسيرُ السعديّ لردّ ﴿وكذلك﴾ إلى ما قبلها («أي: وكما ولَّيْنَا الجن المردة»)، وتقريرُه السنّة («كذلك من سنتنا أن نولي كل ظالم ظالما مثله»)، وحكمُه عليها بأنّها عقوبة («من عقوبات الله العظيمة»)، وردُّه التبعة إلى الظالم («والذنب ذنب الظالم»)، وصورةُ ولاية الظلمة ومقابلتُها بحال الصلاح («أن العباد إذا كثر ظلمهم وفسادهم»): كلُّها بنصّها في تفسير السعديّ (٦:١٢٩).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا بين مذهبين في ترتيب الفساد، وقولُنا إنّ لفظ التولية يسع القرين والوالي، تمهيدٌ منّا لا نصٌّ للسعديّ.\nوتسميتُنا أوّلَ كلامه سنّةً جامعةً وثانيَه صورةً تحتها ترتيبٌ منّا؛ وإنّما قال هو «من سنتنا» ثمّ «ومن ذلك». وقولُنا فانظر في قرنائك قبل سلطانك أولويّةٌ رتّبناها نحن على ترتيب بيانه، ولم يأمر هو بتقديم نظرٍ على نظر.\nوتفريقُنا بين ولايةٍ صغرى في البيت والعمل وولايةٍ عامّة تنزيلٌ منّا؛ وإنّما ذكر هو الولاية العامّة: «ولَّى عليهم ظلمة»، «أئمة عدل وإنصاف».\nوقولُنا إنّ المقدار من جنس الممنوع مع زيادة، وإنّ الصفة مقلوبة، استنباطٌ منّا من قوله «أضعاف ما منعوا».\nوقولُنا إنّ الوالي ثمرةٌ لا بذرة، وإنّ من اشتغل بتبديله دون حاله لم يُبدَّل له إلّا مثلُه، استنباطٌ منّا من ورود الولاية في الطرفين في موضع الأثر.\nوقولُنا إنّ كون الظالم عقوبةً لا يرفع عنه إثمَه، استنباطٌ منّا من نفيه الأجرَ والاحتسابَ عن الآخذين.\nوالأمثلةُ من الأجرة والدَّين والمجالس أمثلةٌ منّا لتنزيل ما ذكره من منع الحقوق الواجبة.\nولم نتعرّض لما يُفعل مع ولاة الجور، وهو بابٌ له أهلُه ومظانُّه.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":130,"reflection":{"text":"«يا معشر الجن والإنس ألم يأتكم رسل منكم يقصون عليكم آياتي وينذرونكم لقاء يومكم هذا قالوا شهدنا على أنفسنا وغرتهم الحياة الدنيا وشهدوا على أنفسهم أنهم كانوا كافرين»: يقرّر الله الحجّةَ على الثقلين: ألم يأتكم رسلٌ منكم يتلون آياتي وينذرونكم هذا اليوم؟ فيقرّون على أنفسهم بأنّ الرسلَ جاءتهم؛ غرّتهم الدنيا فكفروا، فشهدوا على أنفسهم بالكفر؛ فلا عذرَ بعد قيام الحجّة بالرسل. فالحجّةُ قامت، والاعترافُ حصل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الحجّةَ قامت بالرسلِ فلا عذر."},"action":{"text":"اعمل بما جاءت به الرسل، فقد قامت الحجّةُ ولا عذرَ لمن غرّته الدنيا فأعرض."}},{"n":131,"reflection":{"text":"«ذلك أن لم يكن ربك مهلك القرى بظلم وأهلها غافلون»: ذلك الإرسالُ لأنّ الله لا يعذّب أمّةً ظلمًا وهي غافلةٌ لم تُنذَر؛ بل يقيم عليها الحجّةَ بالرسل أوّلًا ثمّ يعاقب المعرضين؛ فعدلُه يقتضي البيانَ قبل العقوبة. فلا عقوبةَ إلا بعد إقامة الحجّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بعدلِ الله الذي يُنذر قبل أن يعاقب."},"action":{"text":"اطمئن إلى عدل الله، فهو لا يعذّب أحدًا إلا بعد إقامة الحجّة عليه بالرسل."}},{"n":132,"reflection":{"text":"«ولكل درجات مما عملوا وما ربك بغافل عما يعملون»، ولكلٍّ من المطيعين والعاصين مراتبُ ومنازلُ بحسب أعمالهم؛ فليس المحسنُ كالمسيء، ولا القليلُ عملًا كالكثير؛ وما ربّك بغافلٍ عن أعمالهم بل يُحصيها ويجازي عليها. فالجزاءُ بحسب العمل بدقّةٍ وعدل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على علوّ الدرجةِ بكثرةِ العمل الصالح."},"action":{"text":"اجتهد في العمل الصالح لترتفع درجتك، فلكلٍّ درجاتٌ بعمله، والله لا يغفل عنه."}}]},{"title":"ربُّك الغنيُّ ذو الرحمة، والعملُ على مكانة","range":[133,135],"theme":"غنى الله عن خلقه ورحمتُه بهم، وحتميّةُ الوعد، والتحدّي بالعمل لتظهر العاقبة","verses":[{"n":133,"reflection":{"text":"«وربك الغني ذو الرحمة إن يشأ يذهبكم ويستخلف من بعدكم ما يشاء كما أنشأكم من ذرية قوم آخرين»: ربّك غنيٌّ عن عباده وطاعتهم، ومع غناه هو ذو رحمةٍ بهم؛ إن يشأ أهلككم وأتى بغيركم كما أنشأكم من نسل أممٍ سابقة؛ فطاعتُكم لنفعكم لا لحاجته إليكم. فهو غنيٌّ عنك، محتاجٌ أنت إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله الغنيِّ ذي الرحمةِ والافتقارُ إليه."},"action":{"text":"اعبد اللهَ مفتقرًا إليه، فهو الغنيُّ عنك، ذو الرحمة بك، القادرُ على استبدالك."}},{"n":134,"reflection":{"text":"«إن ما توعدون لآت وما أنتم بمعجزين»: إنّ ما وُعدتم به من البعث والجزاء آتٍ لا محالة، ولستم بفائتين الله ولا معجزين له بهربٍ أو امتناع؛ فاستعدّوا له. فوعدُ الله واقعٌ، ولا مهربَ من قدرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للوعدِ الآتي الذي لا مهربَ منه."},"action":{"text":"استعدّ للقاء الله وجزائه، فما وُعدت به آتٍ ولن تُعجز الله هربًا."}},{"n":135,"reflection":{"text":"«قل يا قوم اعملوا على مكانتكم إني عامل فسوف تعلمون من تكون له عاقبة الدار إنه لا يفلح الظالمون»: قل لهم تهديدًا: اعملوا على طريقتكم وحالكم، وأنا عاملٌ على ما أنا عليه من الحقّ؛ فسوف تعلمون لمن تكون العاقبةُ الحسنة في الدار الآخرة؛ إنّه لا يفوز الظالمون أبدًا. فالعاقبةُ للمتّقين، والظالمُ لا يفلح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ العاقبةَ للحقّ وأهلِه."},"action":{"text":"اثبت على الحقّ واعمل، فالعاقبةُ للمتّقين، ولن يفلح الظالمون مهما تجبّروا."}}]},{"title":"مفترياتُ المشركين في الأنعامِ والأولاد","range":[136,144],"theme":"قسمتُهم الجائرةُ للحرث والأنعام، وقتلُهم الأولاد، وتحريمُهم ما أحلّ الله افتراءً","verses":[{"n":136,"reflection":{"text":"«وجعلوا لله مما ذرأ من الحرث والأنعام نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا فما كان لشركائهم فلا يصل إلى الله وما كان لله فهو يصل إلى شركائهم ساء ما يحكمون»: جعل المشركون لله نصيبًا من الزرع والأنعام ولأصنامهم نصيبًا؛ فما جعلوه للأصنام لا يصرفونه في وجوه الله، وما جعلوه لله إن اختلط بنصيب الأصنام صرفوه لها؛ فآثروا آلهتهم على الله؛ بئس حكمُهم الجائر. فإيثارُ غير الله عليه غايةُ الجهل والظلم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ حقِّ الله على كلِّ شيء."},"action":{"text":"قدّم حقَّ الله في مالك ووقتك على كلّ شيء، ولا تُؤثر عليه سواه."}},{"n":137,"reflection":{"text":"«وكذلك زين لكثير من المشركين قتل أولادهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم ولو شاء الله ما فعلوه فذرهم وما يفترون»، وكما زُيّنت لهم القسمةُ الجائرة، زيّن شياطينُهم لكثيرٍ منهم قتلَ أولادهم (وأدَ البنات، أو الذبحَ للأصنام) ليُهلكوهم ويخلطوا عليهم دينهم؛ ولو شاء الله لمنعهم؛ فاتركهم وافتراءهم واصبر. فتزيينُ الشيطان يقود إلى أعظم الجرائم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تزيينِ الشيطانِ للجرائم باسم الدين."},"action":{"text":"احذر ما يزيّنه الشيطانُ من منكرٍ يلبسه لباسَ الدين، فتزيينُه يقود للهلاك."}},{"n":138,"reflection":{"text":"«وقالوا هذه أنعام وحرث حجر لا يطعمها إلا من نشاء بزعمهم وأنعام حرمت ظهورها وأنعام لا يذكرون اسم الله عليها افتراء عليه سيجزيهم بما كانوا يفترون»: ابتدع المشركون تحريماتٍ: أنعامًا وزرعًا حرامًا لا يأكله إلا من يشاؤون (خدَمُ الأصنام)، وأنعامًا حرّموا ركوبها، وأنعامًا لا يسمّون الله عليها؛ كلَّ ذلك افتراءً على الله؛ سيجازيهم على كذبهم. فالتشريعُ بالهوى افتراءٌ على الله يُعاقَب عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ التحليلِ والتحريم إلى الله لا الأهواء."},"action":{"text":"لا تحرّم ولا تحلّل إلا بما شرع الله، فابتداعُ التحريم افتراءٌ عليه."}},{"n":139,"reflection":{"text":"«وقالوا ما في بطون هذه الأنعام خالصة لذكورنا ومحرم على أزواجنا وإن يكن ميتة فهم فيه شركاء سيجزيهم وصفهم إنه حكيم عليم»، وقالوا: ما في بطون بعض الأنعام من الأجنّة حلالٌ لذكورنا حرامٌ على نسائنا، فإن وُلد ميّتًا أكله الجميع؛ تحكّمٌ بالهوى بلا دليل؛ سيجازيهم على هذا الوصف الكاذب؛ إنّه حكيمٌ في جزائه، عليمٌ بأحوالهم. فالتحكّمُ في الحلال والحرام بالهوى باطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكيم","العليم"],"heart_state":{"text":"توقّي التحكّمِ في الشرعِ بالهوى والتفريقِ الجائر."},"action":{"text":"لا تفرّق في الحلال والحرام بالأهواء، فالتشريعُ لله الحكيمِ العليم."}},{"n":140,"reflection":{"text":"«قد خسر الذين قتلوا أولادهم سفها بغير علم وحرموا ما رزقهم الله افتراء على الله قد ضلوا وما كانوا مهتدين»: قد خسر خسرانًا عظيمًا من قتلوا أولادهم بجهلٍ وسفهٍ (بالوأد)، ومن حرّموا ما أحلّ الله من الأنعام افتراءً عليه؛ فقد ضلّوا عن الحقّ وما كانوا مهتدين؛ فجمعوا بين قتل النفس والافتراء على الله. فالجهلُ باللهِ يقود إلى أعظم الخسران.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الجهلَ باللهِ يقود إلى الخسران."},"action":{"text":"تعلّم دينك بعلم، فالجهلُ يقود إلى قتلٍ وتحريمٍ وافتراءٍ وخسران."}},{"n":141,"reflection":{"text":"«وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر وآتوا حقه يوم حصاده ولا تسرفوا إنه لا يحب المسرفين»: هو الذي أنشأ البساتينَ مرفوعةً على الأعمدة وممتدّةً على الأرض، والنخلَ والزرعَ مختلفَ الطعوم، والزيتونَ والرمّان متشابهًا في المنظر مختلفًا في الطعم؛ كلوا من ثمره، وأدّوا حقّه (الزكاةَ والصدقة) يومَ حصاده، ولا تسرفوا؛ إنّه لا يحبّ المسرفين. فالنعمةُ تُشكر بأداء حقّها والاعتدالِ فيها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الثمارِ بأداءِ حقِّها وتركِ الإسراف."},"action":{"text":"كُل من رزق الله، وأدِّ زكاته وحقَّه، ولا تسرف، فالله لا يحبّ المسرفين."}},{"n":142,"reflection":{"text":"«ومن الأنعام حمولة وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين»، ومن الأنعام ما يصلح للحمل (كالإبل) وما يُفرش ويُذبح صغيرًا (كالغنم)؛ كلوا مما رزقكم الله منها ولا تحرّموا ما أحلّ اتّباعًا للشيطان في خطواته وتزييناته؛ إنّه لكم عدوٌّ ظاهر العداوة. فتحريمُ الحلال اتّباعٌ لخطوات الشيطان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأكلُ من رزقِ اللهِ الحلالِ وتركُ وساوسِ الشيطان."},"action":{"text":"تمتّع بما أحلّ الله من الأنعام، ولا تتّبع خطوات الشيطان في تحريم الحلال."}},{"n":143,"reflection":{"text":"«ثمانية أزواج من الضأن اثنين ومن المعز اثنين قل آلذكرين حرم أم الأنثيين أما اشتملت عليه أرحام الأنثيين نبئوني بعلم إن كنتم صادقين»: خلق الله ثمانيةَ أصنافٍ من الأنعام أزواجًا؛ من الضأن ذكرًا وأنثى، ومن المعز كذلك؛ فتحدّاهم: أيَّ شيءٍ حرّم الله منها، الذكورَ أم الإناثَ أم ما في الأرحام؟ أخبروني بعلمٍ صادق إن كنتم صادقين في دعوى التحريم؛ فلا حجّةَ لهم. فالتحريمُ يحتاج دليلًا لا هوًى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مطالبةُ كلِّ دعوى تحريمٍ بالدليلِ لا الظنّ."},"action":{"text":"لا تقبل تحريمًا أو تحليلًا بلا دليل، وطالِب كلَّ مدّعٍ ببرهانٍ من الوحي."}},{"n":144,"reflection":{"text":"«ومن الإبل اثنين ومن البقر اثنين قل آلذكرين حرم أم الأنثيين أما اشتملت عليه أرحام الأنثيين أم كنتم شهداء إذ وصاكم الله بهذا فمن أظلم ممن افترى على الله كذبا ليضل الناس بغير علم إن الله لا يهدي القوم الظالمين»، ومن الإبل والبقر ذكرًا وأنثى؛ فأيَّ شيءٍ حرّم الله؟ أم حضرتم حين أوصاكم الله بهذا التحريم فسمعتموه منه؟ لا؛ فلا أحدَ أظلمُ ممّن كذب على الله ليُضلّ الناسَ بلا علم؛ والله لا يهدي الظالمين المفترين. فالافتراءُ على الله لإضلال الناس أظلمُ الظلم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توقّي الافتراءِ على اللهِ وإضلالِ الناسِ بغير علم."},"action":{"text":"لا تقُل على الله ما لم يقُل ولا تُضلّ به الناس، فالافتراءُ عليه أظلمُ الظلم."}}]},{"title":"المحرّماتُ الحقيقيّة، والحجّةُ البالغة","range":[145,150],"theme":"بيانُ ما حرّمه الله حقًّا، وأنّ لله الحجّةَ البالغة، ونقضُ احتجاجِ المشركين بالقدر","verses":[{"n":145,"reflection":{"text":"«قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس أو فسقا أهل لغير الله به فمن اضطر غير باغ ولا عاد فإن ربك غفور رحيم»: قل: لا أجد فيما أوحاه الله إليّ طعامًا محرّمًا إلا الميتةَ والدمَ المسفوحَ ولحمَ الخنزير، فإنّه نجَسٌ، وما ذُبح لغير الله؛ فمن اضطرّ لأكلها غيرَ متجاوزٍ فلا إثم، فربّك غفورٌ رحيم؛ فالتحريمُ محصورٌ فيما حرّمه الله لا فيما ابتدعوه. فالأصلُ في الطعام الحلُّ إلا ما حرّم الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"التقيّدُ بما حرّمه الله وحده في الطعام."},"action":{"text":"لا تحرّم إلا ما حرّم الله، والأصلُ في الطيّبات الحلّ، ورخصةُ الاضطرار رحمة."},"qadiyya":{"title":"قضيّةُ من يملك التحريم: أن يُنسب إلى الله ما لم يُحرّمه","question":"كان أهلُ الجاهليّة يُحرّمون على أنفسهم أصنافًا من الأنعام والحرث، ثمّ **ينسبون ذلك التحريمَ إلى الله**.\nفأمر اللهُ نبيَّه ﷺ أن يحصر ما حُرّم حصرًا: «قل لا أجد فيما أُوحي إليّ محرَّمًا على طاعمٍ يطعمه إلّا أن يكون ميتةً أو دمًا مسفوحًا أو لحمَ خنزيرٍ فإنّه رجس، أو فسقًا أُهلَّ لغير الله به».\nفالقضيّة: لماذا جاء الجوابُ بصيغة الحصر؟ و**من الذي يملك أن يقول: هذا حرام؟** ثمّ: ما حكمُ من نسب إلى الله تحريمًا لم يُحرّمه؟","background":"ولا يُفهم موضعُ الحصر حتى نعرف سياقَ الآية:\nسبقتها آياتٌ في ذمّ المشركين على ما حرّموا من الحلال: ﴿وقالوا هذه أنعامٌ وحرثٌ حِجْر﴾، ﴿وقالوا ما في بطون هذه الأنعام خالصةٌ لذكورنا ومحرَّمٌ على أزواجنا﴾.\nفكانوا **يُنشئون تحريمًا من عند أنفسهم ثمّ يُلبسونه لباسَ الشرع**.\nفجاء الأمرُ بالبيان: أن يُذكر المحرَّمُ بعينه، ليُعلم أنّ ما عداه حلال.\nفالحصرُ إذًا ليس تعدادًا فحسب؛ **إنّه إغلاقٌ للباب**.","what_happened":"بيّن السعديُّ مقصودَ الآية أوّلًا: أنّ اللهَ لمّا ذمّ المشركين على ما حرّموا ونسبوه إليه وأبطل قولَهم، «أمر تعالى رسولَه أن يبيّن للناس ما حرّمه اللهُ عليهم، ليعلموا أنّ ما عدا ذلك حلال».\n⭐ ثمّ قرّر الأصلَ الذي عليه مدارُ الباب: «من نسب تحريمَه إلى الله فهو كاذبٌ مبطل، لأنّ التحريم لا يكون إلّا من عند الله على لسان رسوله».\nفتأمّل قيدين: أنّ مصدرَ التحريم الله، وأنّ طريقَ بلوغه لسانُ رسوله. فليس لأحدٍ بعدهما أن يُنشئ تحريمًا.\nثمّ فصّل المذكورات:\nالميتة: «ما مات بغير ذكاةٍ شرعيّة».\nوالدمُ المسفوح: «وهو الدم الذي يخرج من الذبيحة عند ذكاتها، فإنّه الدمُ الذي يضرّ احتباسُه في البدن، فإذا خرج من البدن زال الضررُ بأكل اللحم».\n⭐ ثمّ استخرج من قيد «المسفوح» **حكمًا بمفهوم المخالفة**: «ومفهومُ هذا اللفظ، أنّ الدم الذي يبقى في اللحم والعروق بعد الذبح، أنّه حلالٌ طاهر».\n**فالقيدُ في الآية أفاد حكمًا في غير المقيَّد**.\nوأمّا الخنزير فقال في علّته: «فإنّه رجس».","the_verdict":"فالحاصلُ أنّ الآية لم تكتفِ بإبطال تحريمهم، بل **أغلقت البابَ الذي دخلوا منه**.\n⭐ والأصلُ الذي قرّره السعديُّ هو مفتاحُ الباب كلِّه: «التحريمُ لا يكون إلّا من عند الله على لسان رسوله».\nفينبني عليه أمران:\nالأوّل: أنّ **الأصلَ في الأشياء الإباحة حتى يرد دليلُ المنع**. ولهذا جاء الحصرُ ليُعلم «أنّ ما عدا ذلك حلال»، كما قال.\nوالثاني: أنّ من حرّم شيئًا بغير دليلٍ فقد نسب إلى الله ما لم يقله، وسمّاه السعديُّ «كاذبًا مبطلًا». وهذا لفظٌ شديد، وشدّتُه في موضعها؛ فإنّ **إنشاء التحريم تشريعٌ، والتشريعُ لله وحده**.\n⭐ وموضعُ الغرابة أنّ الناس **يستعظمون تحليلَ الحرام ويستهينون بتحريم الحلال**، والقرآنُ ساقهما في سياقٍ واحد، بل هذه الآياتُ نزلت في الثاني. فالذي يُحرّم ما أحلّ اللهُ متعدٍّ كالذي يُحلّ ما حرّم، وكلاهما قال على الله ما لم يقل.\nوأمّا استخراجُه الحكمَ من قيد «المسفوح» ففيه درسٌ في العناية باللفظ: أنّ الله لم يقل «أو دمًا» فحسب، بل قيّده. والقيدُ في كلام الله لا يكون عبثًا؛ فأفاد أنّ ما بقي في اللحم والعروق بعد الذبح لا يدخل في التحريم.\n**فمن أهمل القيدَ ضيّق على الناس فيما وسّع اللهُ فيه**.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: لا تقل «هذا حرام» إلّا بدليل. ف**التحريمُ حكمٌ شرعيٌّ لا رأيٌ شخصيّ**. وإذا كرهتَ شيئًا فقل: أكرهه، أو: لا أراه لائقًا؛ ولا تجعل كراهتَك حكمًا لله. فبين «لا أحبّه» و«هو حرام» ما بين رأيٍ وتشريع.\nوالثاني: احذر التضييق كما تحذر التوسّع. فإنّ هذه الآيات نزلت فيمن حرّم الحلال لا فيمن أحلّ الحرام. والذي يُشدّد على الناس بغير دليلٍ يحسب أنّه على جانب الاحتياط؛ **وهو في الحقيقة على جانب القول على الله بلا علم**.\nوالثالث: تعلّمْ العناية بالقيود في النصوص. فقد أفاد قيدُ «المسفوح» حكمًا كاملًا. فإذا قرأتَ نصًّا فانظر في قيوده: من أيّ شيءٍ احترز؟ فإنّ **كلَّ قيدٍ يُخرج شيئًا**؛ والذي يقرأ النصَّ بلا قيوده يحمله على أوسع ممّا أُريد به.","grade":"ma'thur","source":"بيانُ السعديّ لمقصود الآية («أمر تعالى رسوله أن يبين للناس ما حرمه الله عليهم، ليعلموا أن ما عدا ذلك حلال»)، وتقريرُه للأصل («من نسب تحريمه إلى الله فهو كاذب مبطل، لأن التحريم لا يكون إلا من عند الله على لسان رسوله»)، وتفسيرُه للميتة («ما مات بغير ذكاة شرعية») وللدم المسفوح («وهو الدم الذي يخرج من الذبيحة عند ذكاتها»)، واستخراجُه بمفهوم المخالفة («ومفهوم هذا اللفظ، أن الدم الذي يبقى في اللحم والعروق بعد الذبح، أنه حلال طاهر»): كلُّها بنصّها في تفسير السعديّ (٦:١٤٥).","honesty":"وممّا يجب أن يُقال:\nلم نتعرّض لمسألة حصر المحرّمات في هذه الآية وهل هو حصرٌ مطلقٌ أم بالنسبة إلى ما كانوا يحرّمونه، وفيها كلامٌ لأهل العلم، وثمّ محرّماتٌ ثبتت بالسنّة؛ ومظانُّ المسألة كتبُ الأحكام. **ومن أخذ هذه الوقفةَ حصرًا لكلّ محرّمٍ في الشريعة فقد حمّلها ما لا تحتمل**.\nوأمّا قولُنا إنّ الأصل في الأشياء الإباحة فأصلٌ معروفٌ عند أهل العلم، بنيناه ها هنا على قول السعديّ «ليعلموا أن ما عدا ذلك حلال»، ولا ننسب إليه اللفظَ الأصوليّ.\nوأمّا قولُنا إنّ الناس يستعظمون تحليلَ الحرام ويستهينون بتحريم الحلال، **فوصفٌ لواقعٍ نراه، لا إحصاءَ عندنا به**."}},{"n":146,"reflection":{"text":"«وعلى الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما إلا ما حملت ظهورهما أو الحوايا أو ما اختلط بعظم ذلك جزيناهم ببغيهم وإنا لصادقون»، وحرّمنا على اليهود بعضَ الطيّبات (كلَّ ذي مخلبٍ من الطير، وشحومَ البقر والغنم إلا ما استثني) عقوبةً لهم على بغيهم وظلمهم؛ فتحريمُهم كان تشديدًا جزائيًّا لا لخبثِ عينها؛ وإنّا لصادقون في خبرنا؛ فمعاصيهم ضيّقت عليهم ما كان حلالًا. فالمعاصي تجلب الحرمانَ والتضييق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من المعاصي التي تجلب التضييق عقوبةً."},"action":{"text":"اجتنب البغيَ والظلم، فقد يُحرَم بسببهما ما كان مباحًا كما حُرّم اليهود."}},{"n":147,"reflection":{"text":"«فإن كذبوك فقل ربكم ذو رحمة واسعة ولا يرد بأسه عن القوم المجرمين»: فإن كذّبوك يا محمد فذكّرهم بالجمع بين الرجاء والخوف: ربّكم واسعُ الرحمة يمهل ويعفو، لكنّ عذابه لا يُردّ عن المجرمين المصرّين؛ فلا يغترّوا بسعة رحمته فيصرّوا. فرحمتُه واسعة، وبأسُه لا يُردّ عن المجرمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الرجاءِ في رحمتِه والخوفِ من بأسِه."},"action":{"text":"ارجُ رحمةَ الله الواسعة، واخشَ بأسه، ولا تغترّ بالإمهال فتصرّ على الإجرام."}},{"n":148,"reflection":{"text":"«سيقول الذين أشركوا لو شاء الله ما أشركنا ولا آباؤنا ولا حرمنا من شيء كذلك كذب الذين من قبلهم حتى ذاقوا بأسنا قل هل عندكم من علم فتخرجوه لنا إن تتبعون إلا الظن وإن أنتم إلا تخرصون»: سيحتجّ المشركون بالقدر: لو شاء الله ما أشركنا؛ يريدون تبرير باطلهم بمشيئة الله؛ فردّ الله: كذلك احتجّ من قبلهم حتى ذاقوا العذاب؛ قل: هل عندكم علمٌ (لا مجرّد قدر) بأنّ الله رضي شرككم فتُظهروه؟ ما تتّبعون إلا الظنَّ والكذب؛ فالاحتجاجُ بالقدر على المعصية باطل، فالله أمر ونهى وأقدر على الاختيار. فالقدرُ لا يُحتجّ به على ترك الأمر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ردُّ الاحتجاجِ بالقدرِ على المعصية."},"action":{"text":"لا تحتجّ بالقدر على ذنبك، فالله أمرك ونهاك وأقدرك على الاختيار."}},{"n":149,"reflection":{"text":"«قل فلله الحجة البالغة فلو شاء لهداكم أجمعين»: قل: لله الحجّةُ الكاملةُ التي تقطع كلَّ معذرة، فقد أرسل الرسلَ وأنزل الكتبَ وأقام الأدلّة؛ ولو شاء لهداكم جميعًا قهرًا، لكن اقتضت حكمتُه الابتلاءَ والاختيار؛ فلا حجّةَ لأحدٍ عليه. فالحجّةُ البالغةُ لله وحده على خلقه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإذعانُ لحجّةِ الله البالغةِ وتركُ المعاذير."},"action":{"text":"أذعِن لحجّة الله البالغة، فقد أقام عليك الدليل، ولا عذرَ لك في ترك الحق."},"qadiyya":{"title":"قضيّةُ حجّةٍ لا يقبلها صاحبُها من غيره","question":"قال الله: ﴿قل فلله الحجة البالغة فلو شاء لهداكم أجمعين﴾، بعد أن حكى قولهم: ﴿لو شاء الله ما أشركنا ولا آباؤنا﴾.\nوالمشيئةُ التي احتجّوا بها حقٌّ في نفسها، ولم يُنكر القرآنُ شمولَها. **فمَوضع الإشكال أنّ الحجّة بُنيت على مقدّمةٍ صحيحة ثمّ رُدّت.**\nفالقضيّة: كيف يكون القدرُ حقًّا والاحتجاجُ به باطلًا؟ ثمّ: بأيّ شيء يُكشف بطلانُها كشفًا لا تطول معه المناظرة؟ ثمّ: إذا كانوا يعلمون أنّها ليست بحجّة، فما الذي حملهم عليها؟","background":"ولا يستقيم الجوابُ حتى يتقرّر أمران.\nالأوّل أنّ **كون الشيء حقًّا في نفسه غيرُ كونه حجّةً في موضع النزاع**؛ فقد يكون الخبرُ صدقًا ولا يصلح عذرًا لمن اعتذر به.\nوالثاني أنّ **الحجّة لا تصحّ حتى تطّرد مع صاحبها**؛ فمن قبِلها حيث تنفعه وردّها حيث تضرّه، فقد شهد على نفسه أنّها ليست عنده حجّة.\nوالمخاطَبون مشركون احتجّوا بالمشيئة على شركهم وعلى تحريمهم ما أحلّ الله.","what_happened":"ذكر الإمامُ أنّ الأممَ المكذّبة لم تزل تدفع بها دعوةَ الرسل فلم تنفعهم، ثمّ قال: «فعلم أنها حجة فاسدة، وشبهة كاسدة، من عدة أوجه». ثمّ ساق سبعةَ أوجه، اثنان في هذه الآية وخمسةٌ في التي بعدها.\nفمنها: «أن الحجة، لا بد أن تكون حجة مستندة إلى العلم والبرهان»، ثمّ ردّه إلى نصّ الآية فقال: «فلما لم يخرجوه علم أنه لا علم عندهم».\nثمّ قال: «ومنها: أن الحجة لله البالغة، التي لم تبق لأحد عذرا، التي اتفقت عليها الأنبياء والمرسلون».\nثمّ قال: «ومنها: أن الله تعالى أعطى كل مخلوق، قدرة، وإرادة، يتمكن بها من فعل ما كلف به، فلا أوجب الله على أحد ما لا يقدر على فعله، ولا حرم على أحد ما لا يتمكن من تركه، فالاحتجاج بعد هذا بالقضاء والقدر، ظلم محض وعناد صرف».\nثمّ قال: «ومنها: أن الله تعالى لم يجبر العباد على أفعالهم، بل جعل أفعالهم تبعا لاختيارهم، فإن شاءوا فعلوا، وإن شاءوا كفوا. وهذا أمر مشاهد لا ينكره إلا من كابر، وأنكر المحسوسات، فإن كل أحد يفرق بين الحركة الاختيارية والحركة القسرية، وإن كان الجميع داخلا في مشيئة الله».\n⭐ ثمّ قال: «ومنها: أن المحتجين على المعاصي بالقضاء والقدر يتناقضون في ذلك»، **ثمّ بيّن ذلك بامتحانٍ واقع**: «فإنهم لا يمكنهم أن يطردوا ذلك، بل لو أساء إليهم مسيء بضرب أو أخذ مال أو نحو ذلك، واحتج بالقضاء والقدر لما قبلوا منه هذا الاحتجاج، ولغضبوا من ذلك أشد الغضب».\nثمّ ختم فقال: «ومنها: أن احتجاجهم بالقضاء والقدر ليس مقصودا، ويعلمون أنه ليس بحجة، وإنما المقصود منه دفع الحق، ويرون أن الحق بمنزلة الصائل، فهم يدفعونه بكل ما يخطر ببالهم من الكلام وإن كانوا يعتقدونه خطأ».","the_verdict":"فالحاصلُ أنّ نقض الاحتجاج لم يقع بإنكار القدر. فقد أثبت أنّ الجميع داخلٌ في مشيئة الله في نفس الموضع الذي نفى فيه الجبر، وأثبت للعبد قدرةً وإرادةً وفعلًا تابعًا لاختياره. **فالباطلُ نقلُ القدر من موضع الإيمان إلى موضع الاعتذار.** ولذلك جاء حكمُه بالظلم والعناد مفرَّعًا بالفاء على إعطاء القدرة، وهما عندنا وصفا قصد.\n⭐ ثمّ انظر إلى وجهين يُقامان على الخصم من نفسه: أن يُخرج علمًا فلا يجد، وأن يَطرد أصلَه فلا يستطيع. وسائرُها يُقام عليه من خارج، باتّفاق الأدلّة وبالمشاهدة؛ وقد جعل الإمامُ إنكارَ المشاهدة مكابرةً. وأخصُّهما بالنزاع عندنا الثاني، لأنّ الأوّل يطلب دليلًا وهو قد يدّعيه، والثاني يطلب اطّرادًا يُكشف من نفسه. وعلى لفظه «يطردوا» بنينا: **فالحجّةُ إن لم تطّرد سقطت.**\n⭐ وموضعُ امتحانه ضربٌ أو أخذُ مال؛ فليس بابًا نظريًّا، بل مسًّا في البدن والمال. وقولُه «ولغضبوا من ذلك أشد الغضب» أدقُّ عندنا من أن يقال: لأنكروا عليه؛ إذ الغضبُ انفعالٌ لا يُصطنع.\nوأمّا لِمَ لم ينفعهم انكشافُ تناقضهم، فجوابُه في الوجه الأخير: أنّ الاحتجاج ليس مقصودًا، وأنّهم يدفعون الحقّ بما يخطر بالبال وإن اعتقدوه خطأ. **فمن كان مقصودُه الدفعَ لم يضرّه انكشافُ حجّته**؛ إذ لم يبنِ عليها.\nوموضعُ الغلط أمران: أن يُظنّ ردُّ الاحتجاج ردًّا للقدر، وقد منع لفظُه ذلك؛ وأن يستفرغ المرءُ عمرَه في مناظرة من لا يقصد الحجّة.","for_you":"فأمّا الذي تخرج به فثلاثة.\n**الأوّل: اعرض عذرك على نفسك مقلوبًا.** إذا قلتَ عن تقصيرك: هذا مقدَّرٌ عليّ، فافرض أنّ من أخذ مالك قال اللفظ نفسَه. والامتحانُ أن تنطق بالكلمتين في مجلسٍ واحد، وترى أيّهما تُصدّق.\n**والثاني: راقب انفعالك عند الإلزام قبل جوابك.** فمن وجد الغضبَ سابقًا للنظر فهو يدفع لا يبحث. والامتحانُ أن تسكت يومًا ثمّ تعود؛ فما بقي بعد ذهاب الغضب فهو حجّتك.\n**والثالث: افصل بين ما دُفعتَ إليه وما مشيتَ إليه.** والامتحانُ أن تسمّي في الذنب الذي تعتذر عنه الخطوةَ الواحدة التي كنتَ تقدر على تركها؛ فإن سمّيتَها بطل العذر.","grade":"ma'thur","source":"مطلعُ الأوجه («فعلم أنها حجة فاسدة»)، ووجهُ العلم والبرهان («ومنها: أن الحجة، لا بد أن تكون»)، ووجهُ الحجّة البالغة («ومنها: أن الحجة لله البالغة»)، ووجهُ القدرة والإرادة وما فُرّع عليه («ومنها: أن الله تعالى أعطى كل مخلوق»)، ووجهُ نفي الجبر والمشاهدة («ومنها: أن الله تعالى لم يجبر العباد»)، ووجهُ التناقض وامتحانُه («فإنهم لا يمكنهم أن يطردوا ذلك»)، ووجهُ أنّ الاحتجاج غيرُ مقصود مع الصائل («ومنها: أن احتجاجهم بالقضاء والقدر ليس مقصودا»): كلُّها بنصّها في تفسير السعديّ (٦:١٤٨ و٦:١٤٩).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا بين كون الشيء حقًّا وكونه حجّةً في موضع النزاع، وجعلُنا الاطّرادَ شرطًا في الحجّة، وقولُنا إنّ الباطل نقلُ القدر من موضع الإيمان إلى موضع الاعتذار، **صياغةٌ منّا**؛ وإنّما جاء الطردُ في كلامه إخبارًا عن عجزهم، لا قاعدةً قرّرها.\nوقسمتُنا الأوجهَ إلى ما يُقام على الخصم من خارج وما يُلزَم به من نفسه، وتفضيلُنا وجهَ الطرد على وجه العلم، **تقسيمٌ منّا وترجيحٌ منّا**؛ وإن كان قد ميّز بعضَها بردّه إلى نصّ الآية.\nوقولُنا إنّ الغضب انفعالٌ لا يُصطنع، وقولُنا إنّ من قصد الدفعَ لم يضرّه انكشافُ حجّته، **استنباطان منّا**؛ وحملُنا وصفَي الظلم والعناد على أنّهما وصفا قصد فهمٌ منّا للفظه.\nوكلامُه واردٌ في المشركين وفي المحتجّين على المعاصي بالقدر؛ **فنقلُنا الميزانَ إلى عذر المسلم عن تقصيره توسيعٌ منّا**، والأمثلةُ في ما تخرج به أمثلةٌ منّا، ومن رأى أنّا وسّعنا فليردّه."}},{"n":150,"reflection":{"text":"«قل هلم شهداءكم الذين يشهدون أن الله حرم هذا فإن شهدوا فلا تشهد معهم ولا تتبع أهواء الذين كذبوا بآياتنا والذين لا يؤمنون بالآخرة وهم بربهم يعدلون»: قل: أحضِروا شهداءكم الذين يشهدون أنّ الله حرّم ما ابتدعتموه؛ فإن شهدوا زورًا فلا تصدّقهم ولا تشهد معهم بالباطل؛ ولا تتّبع أهواءَ المكذّبين بآيات الله المنكرين للآخرة الذين يجعلون لربّهم عِدلًا؛ فلا يُتّبع في الدين إلا الوحيُ لا الأهواء. فالحقُّ لا يُثبت إلا بالبيّنة من الوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ متابعةِ الباطلِ ولو شهد به شهود."},"action":{"text":"لا تشهد بباطلٍ ولا تتّبع أهواءَ المكذّبين، والزم ما ثبت بالوحي وحده."}}]},{"title":"الوصايا الجامعة، والصراطُ المستقيم","range":[151,155],"theme":"عشرُ وصايا محكمة، والأمرُ باتّباع صراطِ الله الواحد وتركِ سبل الفرقة","verses":[{"n":151,"reflection":{"text":"«قل تعالوا أتل ما حرم ربكم عليكم ألا تشركوا به شيئا وبالوالدين إحسانا ولا تقتلوا أولادكم من إملاق نحن نرزقكم وإياهم ولا تقربوا الفواحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله إلا بالحق ذلكم وصاكم به لعلكم تعقلون»: قل: تعالوا أتلُ عليكم ما حرّم ربّكم حقًّا: ألّا تشركوا به شيئًا، وأن تُحسنوا للوالدين، ولا تقتلوا أولادكم خوفَ الفقر فالله يرزقكم وإيّاهم، ولا تقربوا الفواحشَ ظاهرَها وباطنَها، ولا تقتلوا النفسَ التي حرّم الله إلا بحقّ؛ ذلكم وصّاكم به لتعقلوا. فهذه وصايا محكمةٌ اتّفقت عليها الشرائع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الوصايا المحكمةِ والعملُ بها."},"action":{"text":"احفظ وصايا الله: وحّده، وأحسِن لوالديك، وصُن النفوسَ والأعراض، ولا تقتل ولدًا خوفَ فقر."}},{"n":152,"reflection":{"text":"«ولا تقربوا مال اليتيم إلا بالتي هي أحسن حتى يبلغ أشده وأوفوا الكيل والميزان بالقسط لا نكلف نفسا إلا وسعها وإذا قلتم فاعدلوا ولو كان ذا قربى وبعهد الله أوفوا ذلكم وصاكم به لعلكم تذكرون»، ولا تقربوا مالَ اليتيم إلا بما فيه إصلاحُه وتنميتُه حتى يبلغ رشدَه، وأتمّوا الكيلَ والوزنَ بالعدل، ولا يكلّف الله فوق الطاقة، واعدلوا في القول ولو على قريب، وأوفوا بعهد الله؛ ذلكم وصّاكم به لتتذكّروا. فحفظُ الأمانةِ والعدلُ في المعاملة والقولِ والوفاءُ بالعهد من الوصايا الجامعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأمانةُ والعدلُ في المالِ والقولِ والوفاءُ بالعهد."},"action":{"text":"احفظ مالَ اليتيم، وأوفِ الكيلَ والوزن، واعدل في قولك ولو على قريب، وأوفِ بعهدك."},"qadiyya":{"title":"قضيّةُ العدل في نقل مقالة من تكره","question":"قال الله: ﴿وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَىٰ﴾.\n\nوالآيةُ واقعةٌ بين إيفاء الكيل والميزان وبين الوفاء بعهد الله، وقيدُها ﴿ولو كان ذا قربى﴾ يجري على الألسنة في الشهادة والقضاء؛ فينصرف الذهنُ إلى أنّ المراد عدلُ الحاكم بين خصمين حاضرين.\n\nفالقضيّة: هل العدل المأمور به في القول محصورٌ في الحكم بين المتخاصمين؟ ثمّ: ما حدُّ العدل إذا تكلّمتَ في رجلٍ تكرهه أو في مذهبه؟ ثمّ: هل يكفيك أن تصدُق في النقل حتى تكون قد عدلت؟","background":"ويحتاج القارئُ قبل الجواب إلى أمرين.\n\nأوّلهما أنّ القول أعمُّ من الحكم؛ فالحكمُ قولٌ، وليس كلُّ قولٍ حكمًا. فإذا عُلّق الأمرُ على ﴿قلتم﴾ لم يكن قصرُه على مجلس القضاء ظاهرًا من اللفظ.\n\nوالثاني الفرق بين **الكذب في النقل** و**الميل فيه**. فالكذبُ أن تنسب إلى صاحب المقالة ما لم يقله، والميلُ أن تصدُق في اللفظ وتبخس في العرض. والأوّلُ يتحاماه أكثرُ الناس، والثاني يقع فيه من يشهد على نفسه بالصدق. وداعيه جهتان لا جهةٌ واحدة: محبّةٌ تحمل على كتمان ما يلزم بيانه، وكراهةٌ تحمل على البخس.","what_happened":"مضى السعديُّ على ترتيب الآية.\n\nفلمّا بلغ ﴿وأوفوا الكيل والميزان بالقسط﴾ قال: «أي: بالعدل والوفاء التام».\n\n⭐ ثمّ بلغ ﴿وإذا قلتم﴾ ففسّر القول بثلاثة أشياء: «قولا تحكمون به بين الناس، وتفصلون بينهم الخطاب، وتتكلمون به على المقالات والأحوال».\n\nثمّ فسّر ﴿فاعدلوا﴾ فقال: «في قولكم، بمراعاة الصدق فيمن تحبون ومن تكرهون، والإنصاف، وعدم كتمان ما يلزم بيانه».\n\nثمّ صرّح بالحكم فقال: «فإن الميل على من تكره بالكلام فيه أو في مقالته من الظلم المحرم».\n\n⭐ ثمّ لم يقف عند المنع حتى أوجب، فقال: «بل إذا تكلم العالم على مقالات أهل البدع، فالواجب عليه أن يعطي كل ذي حق حقه، وأن يبين ما فيها من الحق والباطل، ويعتبر قربها من الحق وبُعدها منه».\n\nثمّ ختم كلامه على ﴿فاعدلوا﴾ بالنقل عن غيره فقال: «وذكر الفقهاء أن القاضي يجب عليه العدل بين الخصمين، في لحظه ولفظه».\n\nثمّ انتقل إلى ﴿وبعهد الله أوفوا﴾ فأدخل فيه عهد الله وعهد الخلق.","the_verdict":"فأمّا الأوّل فقد أجاب عنه الإمامُ بأن أدخل في ﴿قلتم﴾ ثلاثة، آخرُها الكلامُ على المقالات والأحوال؛ فلم يجعل الآية في مجلس الحكم وحده. وهو دقيقٌ لأنّ **اللفظ مطلقٌ في القول، والقضاءُ بعضُ القول لا كلُّه**.\n\nوأمّا حدُّ العدل عنده فيمن تكره، فذكر فيه الصدق فيمن تُحبّ ومن تكره، والإنصاف، وترك كتمان ما يلزم بيانه. ⭐ فتأمّل أنّه لم يقتصر على الصدق. فمن نقل مقالة خصمه بلفظها ثمّ طوى ما فيها من حقّ فقد صدق ولم ينصف؛ وهذا جوابُ الثالث: **الصدقُ شرطٌ في العدل، وليس هو العدل**.\n\nوموضعُ الشدّة قولُه في الميل إنّه «من الظلم المحرم»؛ فجعله من الظلم، لا من سوء الخلق وحده. وذكر معه الموضعين: «بالكلام فيه أو في مقالته»؛ فالرجلُ يُظلم في نفسه ويُظلم في قوله.\n\n⭐ ثمّ الأدقّ عندي ما ختم به: **أنّه لم يقف عند قسمة المقالة إلى حقّ وباطل حتى أوجب تقدير المسافة**، فقال «ويعتبر قربها من الحق وبُعدها منه». فالحكمُ بالبطلان يقول لك إنّها ليست حقًّا، وتقديرُ القرب والبعد يقول لك كم بينها وبين الحقّ؛ ولا يقدر على الثاني إلّا من عرف المقالة معرفةَ صاحبها. وهذا الإيجابُ عنده مقيّدٌ بأمرين: أن يكون المتكلّم «العالم»، وأن يكون الكلام «على مقالات أهل البدع».\n\nوههنا يقع الغلط عندي. **فإنّ الرجل يحسب إنصاف المخالف تليينًا له، فيرى أنّ أنفع ما يصنع أن يُورد أسوأ ما في قوله**؛ وهذا الصنيعُ داخلٌ عندي فيما سمّاه ميلًا، وقد جعل ضدَّه في ذلك الموضع واجبًا لا فضيلةً يأتي بها إن شاء.\n\nوما حكاه عن الفقهاء تمامُ الباب: أوجبوا العدل «في لحظه ولفظه»، فبلغ الأمرُ عندي إلى ما دون العبارة. وأمّا ﴿ولو كان ذا قربى﴾ فلم يعرض له ههنا بحرف، وأقربُ ما في كلامه إليه قولُه «فيمن تحبون».","for_you":"فأمّا الذي تعمل به فثلاثة.\n\nالأوّل: **أن تنقل قبل أن تردّ**. فاكتب مقالة مخالفك بعبارةٍ لو قرأها لقال: هذا قولي. واختبارُه أن تعرضها على من يقول بها، فإن استدرك عليك فنقلُك ناقص، وردُّك على الناقص ردٌّ على غير قول صاحبه.\n\nوالثاني: **أن تقدّر المسافة لا أن تكتفي بالحكم**. فإذا حكمت على قولٍ بالبطلان فاذكر أين هو من الحقّ، أقريبٌ منه أم بعيد. وقد أوجب السعديُّ هذا على العالم إذا تكلّم على مقالات أهل البدع، فإن كنتَ في ذلك الموضع فهو فرضك، وإلّا فهو أدبك.\n\nوالثالث: **أن تمتحن ألفاظك بقلب الجهة**. فانظر في الكلمة التي اخترتها لوصف خصمك أو قوله، ثمّ سل نفسك: أكنتُ أختارها لو صدر ذلك عمّن أحبّ؟ فإن كان لا فبدّلها؛ فإنّ الميل قد دخل عليك من حيث لا تحتسب.","grade":"ma'thur","source":"تفسيرُ السعديّ لقوله ﴿وأوفوا الكيل والميزان بالقسط﴾ («أي: بالعدل والوفاء التام»)، وتفسيرُه ﴿وإذا قلتم﴾ بثلاثة أنواع من القول («قولا تحكمون به بين الناس»)، وتفسيرُه ﴿فاعدلوا﴾ («في قولكم، بمراعاة الصدق»)، وحكمُه على الميل («فإن الميل على من تكره»)، وإيجابُه البيان على العالم في مقالات أهل البدع («بل إذا تكلم العالم»)، ونقلُه عن الفقهاء في القاضي («وذكر الفقهاء أن القاضي»)، وكلامُه على ﴿وبعهد الله أوفوا﴾: كلُّها بنصّها في تفسير السعديّ (٦:١٥٢).","honesty":"وممّا يجب أن يُقال:\n\nتفريقُنا بين الكذب في النقل والميل فيه تمهيدٌ منّا لا نصٌّ له، وإن كان مبنيًّا على جمعه بين الصدق والإنصاف وترك الكتمان. وجعلُنا داعيَ الميل جهتين ترتيبٌ منّا على قوله «فيمن تحبون ومن تكرهون».\n\nوقولُنا إنّ الصدق شرطٌ في العدل وليس هو العدل، استنباطٌ منّا من كونه لم يقتصر على الصدق.\n\nوأمّا تسميتُنا اعتبارَ القرب والبعد تقديرًا للمسافة، وقولُنا إنّه لا يقدر عليه إلّا من عرف المقالة معرفةَ صاحبها، فتحليلٌ منّا. وكذلك وصفُنا الغلطَ بأنّ صاحبه يحسب الإنصاف تليينًا، وإدخالُنا إيرادَ أسوأ ما في القول تحت لفظ «الميل»؛ فهو تنزيلٌ منّا لا نصٌّ له.\n\nوقولُنا إنّ الأمر بلغ إلى ما دون العبارة استخراجٌ منّا من لفظ الفقهاء «في لحظه ولفظه»، وهو ممّا حكاه عنهم ولم يُنشئه، فلا يُنسب إليه على أنّه اختيارُه.\n\nوقد سكت عن ﴿ولو كان ذا قربى﴾ في هذا الموضع، وردُّنا له إلى قوله «فيمن تحبون» تقريبٌ منّا.\n\nوأمّا الثلاثةُ في آخر القضيّة فتطبيقٌ منّا، ليس فيها لفظٌ له.\n\nومن رأى أنّا وسّعنا فليردّه."}},{"n":153,"reflection":{"text":"«وأن هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون»، وأنّ هذا الذي وصّيتكم به هو صراطي المستقيمُ الموصلُ إليّ فاتّبعوه وحده، ولا تتّبعوا الطرقَ المخالفةَ (البدعَ والأهواء) فتفرّقكم عن طريق الله؛ ذلكم وصّاكم به لتتّقوا. (خطّ النبيُّ ﷺ خطًّا وخطوطًا وقال: هذا سبيل الله، وهذه سبلٌ على كلّ سبيلٍ شيطان). فالحقُّ واحدٌ والسبلُ متفرّقة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الصراطِ الواحدِ وتركُ سبلِ الفرقة."},"action":{"text":"الزم صراطَ الله الواحد المستقيم، واحذر السبلَ المتفرّقة التي تبعدك عنه."}},{"n":154,"reflection":{"text":"«ثم آتينا موسى الكتاب تماما على الذي أحسن وتفصيلا لكل شيء وهدى ورحمة لعلهم بلقاء ربهم يؤمنون»: ثمّ آتينا موسى التوراةَ إتمامًا للنعمة على من أحسن العملَ بها، وتفصيلًا لما يحتاجونه من الأحكام، وهدًى من الضلال، ورحمةً لمن اتّبعها؛ لعلّهم يؤمنون بلقاء ربّهم فيستعدّون. فالكتبُ نعمةٌ تُتمّ الإحسانَ وتهدي وترحم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ نعمةِ الكتابِ هدًى ورحمة."},"action":{"text":"اعرف قدرَ كتاب الله هدًى ورحمة، واعمل به لتؤمن بلقاء ربّك وتستعدّ له."}},{"n":155,"reflection":{"text":"«وهذا كتاب أنزلناه مبارك فاتبعوه واتقوا لعلكم ترحمون»، وهذا القرآنُ كتابٌ أنزلناه كثيرَ البركة والخير؛ فاتّبعوه بالعمل به، واتّقوا الله بامتثال أمره واجتناب نهيه؛ لعلّكم تُرحمون؛ فاتّباعُ القرآن والتقوى سببُ الرحمة. فبركةُ القرآن تُنال باتّباعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ القرآنِ المباركِ والتقوى لنيلِ الرحمة."},"action":{"text":"اتّبع القرآنَ المبارك واعمل به مع التقوى، فذاك سبيلُ رحمة الله لك."}}]},{"title":"قطعُ الأعذار، وعدمُ نفعِ الإيمانِ عند الآيات","range":[156,159],"theme":"إنزالُ القرآن يقطع معاذيرهم، وأنّ إيمانَ وقتِ الآياتِ لا ينفع، والبراءةُ من التفرّق","verses":[{"n":156,"reflection":{"text":"«أن تقولوا إنما أنزل الكتاب على طائفتين من قبلنا وإن كنا عن دراستهم لغافلين»: أنزلنا القرآنَ لئلّا تحتجّوا يومَ القيامة بأنّ الكتبَ إنّما نزلت على اليهود والنصارى قبلكم وكنتم غافلين عن دراستهم لا تفهمون لغتهم؛ فقطع الله هذا العذر بإنزال القرآن بلسانكم. فالقرآنُ حجّةٌ تقطع كلَّ معذرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ القرآنِ الذي قطع العذر."},"action":{"text":"اشكر أن أنزل الله عليك القرآنَ بلسانك، فلا عذرَ لك في تركه بعد بيانه."}},{"n":157,"reflection":{"text":"«أو تقولوا لو أنا أنزل علينا الكتاب لكنا أهدى منهم فقد جاءكم بينة من ربكم وهدى ورحمة فمن أظلم ممن كذب بآيات الله وصدف عنها سنجزي الذين يصدفون عن آياتنا سوء العذاب بما كانوا يصدفون»: أو تحتجّوا بأنّكم لو أُنزل عليكم كتابٌ لكنتم أهدى من أهل الكتاب؛ فقد جاءكم من ربّكم حجّةٌ بيّنةٌ وهدًى ورحمة (القرآن)؛ فلا أحدَ أظلمُ ممّن كذّب بآيات الله وأعرض عنها؛ سنجزي المعرضين أشدَّ العذاب بإعراضهم. فالإعراضُ عن الحجّة بعد قيامها أظلمُ الظلم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على آيات الله وتوقّي الإعراضِ عنها."},"action":{"text":"لا تُعرض عن آيات الله بعد أن بلغتك، فالمعرضُ عنها له سوءُ العذاب."}},{"n":158,"reflection":{"text":"«هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك يوم يأتي بعض آيات ربك لا ينفع نفسا إيمانها لم تكن آمنت من قبل أو كسبت في إيمانها خيرا قل انتظروا إنا منتظرون»: ما ينتظر المعرضون إلا مجيءَ ملائكة الموت، أو مجيءَ ربّك للفصل يومَ القيامة، أو بعضَ آياته الكبرى كطلوع الشمس من مغربها؛ فيومَ تأتي تلك الآيةُ لا ينفع نفسًا إيمانُها إن لم تكن آمنت قبلُ، ولا توبةُ عاصٍ؛ فبادروا قبل ذلك؛ قل: انتظروا إنّا منتظرون. فالإيمانُ ينفع قبل معاينة العلامات الكبرى لا بعدها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ والعملِ قبل فواتِ الأوان."},"action":{"text":"آمن واعمل الصالحَ الآن، فيومَ تأتي الآياتُ الكبرى لا ينفع إيمانٌ جديد."}},{"n":159,"reflection":{"text":"«إن الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء إنما أمرهم إلى الله ثم ينبئهم بما كانوا يفعلون»: الذين مزّقوا دينهم فرقًا وأحزابًا كلٌّ يتعصّب لبدعته، لست منهم في شيءٍ ولا هم منك؛ إنّما أمرُهم إلى الله يحكم فيهم، ثمّ يخبرهم بأعمالهم فيجازيهم؛ فالتفرّقُ في الدين مذموم، والواجبُ الاجتماعُ على الحقّ. فالبراءةُ من التفرّق والتعصّبِ للبدع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ جماعةِ الحقّ والبراءةُ من التفرّق والبدع."},"action":{"text":"الزم دين الله كما جاء، ولا تكن من المفرّقين المتعصّبين لبدعةٍ أو حزب."}}]},{"title":"جزاءُ الحسنة عشرًا، وإخلاصُ الحياةِ لله","range":[160,165],"theme":"مضاعفةُ الحسنات وعدلُ الجزاء، وإعلانُ التوحيد الخالص، وأنّ العبادَ خلائفُ مبتلَون","verses":[{"n":160,"reflection":{"text":"«من جاء بالحسنة فله عشر أمثالها ومن جاء بالسيئة فلا يجزى إلا مثلها وهم لا يظلمون»: من عمل حسنةً ضاعفها الله عشرَ أمثالها فضلًا (وقد تزيد)، ومن عمل سيّئةً لم يُجزَ إلا بمثلها عدلًا، وهم لا يُظلمون شيئًا؛ ففضلُه في الحسنات، وعدلُه في السيّئات. فباب الفضل واسع، فأكثِر من الحسنات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من الحسناتِ طمعًا في مضاعفةِ الله."},"action":{"text":"أكثِر من الحسنات، فالله يضاعفها عشرًا فأكثر، ولا يجزي السيّئةَ إلا بمثلها."}},{"n":161,"reflection":{"text":"«قل إنني هداني ربي إلى صراط مستقيم دينا قيما ملة إبراهيم حنيفا وما كان من المشركين»: قل: هداني ربّي إلى الطريق المستقيم، دينًا مستقيمًا قائمًا بمصالح الدنيا والآخرة، ملّةِ إبراهيم المائلةِ عن الشرك إلى التوحيد؛ وما كان إبراهيمُ من المشركين؛ فأعلن اتّباعَه للحنيفيّة. فدينُ الحقّ هو ملّةُ إبراهيم القائمة على التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتزازُ بالهدايةِ إلى دينِ إبراهيمَ القويم."},"action":{"text":"اعتزّ بهدايتك إلى دين الحقّ القيّم، ملّةِ إبراهيم، واثبت على التوحيد."}},{"n":162,"reflection":{"text":"«قل إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين»: قل: إنّ صلاتي وذبحي وعبادتي، وكلَّ ما في حياتي وما يكون عند مماتي، خالصٌ لله ربّ العالمين لا لغيره؛ فأعلن أنّ حياته كلَّها لله؛ فالتوحيدُ أن يكون العبدُ كلُّه لله. فاجعل حياتك ومماتك خالصةً لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الحياةِ والعبادةِ كلِّها لله."},"action":{"text":"اجعل صلاتك ونسكك وحياتك ومماتك لله وحده، فذاك حقيقةُ التوحيد."}},{"n":163,"reflection":{"text":"«لا شريك له وبذلك أمرت وأنا أول المسلمين»: لا شريكَ له في ربوبيّته وألوهيّته وعبادته؛ وبهذا الإخلاص أمرني ربّي، وأنا أوّلُ المسلمين من هذه الأمّة انقيادًا لله؛ فالتوحيدُ نفيُ الشريك مع كمال الانقياد. فأخلِص التوحيدَ وكن سبّاقًا إلى الطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نفيُ الشريكِ عن الله والمسارعةُ إلى الإسلام."},"action":{"text":"انفِ الشريكَ عن الله في عبادتك، وسابِق إلى الانقياد لأمره والإسلام له."}},{"n":164,"reflection":{"text":"«قل أغير الله أبغي ربا وهو رب كل شيء ولا تكسب كل نفس إلا عليها ولا تزر وازرة وزر أخرى ثم إلى ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون»: قل: أأطلب ربًّا غيرَ الله وهو ربُّ كلِّ شيءٍ وخالقه؟ ولا تكتسب نفسٌ إثمًا إلا عليها وحدها، ولا تحمل نفسٌ ذنبَ أخرى؛ ثمّ إلى ربّكم مرجعكم فيخبركم بما اختلفتم فيه فيفصل بينكم؛ فكلٌّ مسؤولٌ عن عمله. فلا ربَّ سوى الله، ولكلٍّ عملُه ووزرُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالربوبيّةِ وتحمّلُ مسؤوليّةِ العمل."},"action":{"text":"اتّخذ الله وحده ربًّا، واعلم أنّك مسؤولٌ عن عملك وحدك، فأصلحه."}},{"n":165,"reflection":{"text":"«وهو الذي جعلكم خلائف الأرض ورفع بعضكم فوق بعض درجات ليبلوكم في ما آتاكم إن ربك سريع العقاب وإنه لغفور رحيم»: هو الذي جعلكم خلفاءَ يخلف بعضُكم بعضًا في عمارة الأرض، وفاوت بينكم في الأرزاق والمواهب درجاتٍ ليختبركم فيما أعطاكم: أتشكرون أم تكفرون، أيُحسن الغنيُّ ويصبر الفقير؟ إنّ ربّك سريعُ العقاب لمن عصى، وإنّه لغفورٌ رحيمٌ لمن تاب؛ خُتمت السورةُ بالجمع بين الترهيب والترغيب. فالتفاوتُ ابتلاءٌ، والحياةُ اختبار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سريع العقاب","الغفور","الرحيم"],"heart_state":{"text":"إدراكُ أنّ التفاوتَ في الدنيا ابتلاءٌ يُشكر فيه ويُصبر."},"action":{"text":"اعلم أنّ ما أُعطيت أو مُنعت ابتلاءٌ، فاشكر واصبر، بين رجاءِ مغفرتِه وخوفِ عقابه."}}]}],"coverage":{"covered":165,"total":165}};
